export function createAdministrationModule(ctx) {
	const { root, state, costTypeLabels, unitLabels } = ctx
	const api = (...args) => ctx.api(...args)
	const articleUrl = (...args) => ctx.articleUrl(...args)
	const articleGroupUrl = () => `${ctx.apiBase}/article-groups`
	const commercialUrl = (...args) => ctx.commercialUrl(...args)
	const contactsByCategory = (...args) => ctx.contactsByCategory(...args)
	const esc = (...args) => ctx.esc(...args)
	const field = (...args) => ctx.field(...args)
	const formatMoney = (...args) => ctx.formatMoney(...args)
	const formatQuantity = (...args) => ctx.formatQuantity(...args)
	const funeralScope = (...args) => ctx.funeralScope(...args)
	const hydrateServiceDraft = (...args) => ctx.hydrateServiceDraft(...args)
	const listOptions = (...args) => ctx.listOptions(...args)
	const quantityStep = (...args) => ctx.quantityStep(...args)
	const render = (...args) => ctx.render(...args)
	const title = (...args) => ctx.title(...args)
	const confirmAction = (...args) => ctx.confirmAction(...args)
	const notifySuccess = (...args) => ctx.notifySuccess(...args)
	const notifyError = (...args) => ctx.notifyError(...args)
	const download = (...args) => ctx.download(...args)
	const promptAction = (...args) => ctx.promptAction(...args)
	const systemCheckUrl = () => `${ctx.apiBase}/system-check`
	const installationSettingsUrl = () => `${ctx.apiBase}/installation-settings`
	const reportSummaryUrl = () => `${ctx.apiBase}/reports/summary`
	const retentionUrl = () => `${ctx.apiBase}/operations/retention`
	const cockpitUrl = () => `${ctx.apiBase}/operations/cockpit`
	const backupsUrl = () => `${ctx.apiBase}/operations/backups`
	const onboardingUrl = () => `${ctx.apiBase}/operations/onboarding`

	async function loadOnboarding() {
		state.onboarding = await api(onboardingUrl(), { feedback: false, loadingLabel: 'Ersteinrichtung wird geprüft …' })
		return state.onboarding
	}

	function onboardingView() {
		const data = state.onboarding || { settings: {}, groups: { member: {}, admins: [] }, users: [], branches: [], checks: [] }
		const settings = data.settings || {}
		const memberUids = new Set(data.groups?.member?.uids || [])
		const adminUids = new Set((data.groups?.admins || []).flatMap((group) => group.uids || []))
		const users = (data.users || []).map((user) => `<tr><td><b>${esc(user.displayName)}</b><small>${esc(user.uid)}${user.email ? ` · ${esc(user.email)}` : ''}</small></td><td><input type="checkbox" data-onboarding-member value="${esc(user.uid)}" ${memberUids.has(user.uid) ? 'checked' : ''} aria-label="${esc(user.displayName)} als Fachbenutzer"></td><td><input type="checkbox" data-onboarding-admin value="${esc(user.uid)}" ${adminUids.has(user.uid) || (!adminUids.size && user.uid === data.currentUid) ? 'checked' : ''} aria-label="${esc(user.displayName)} als Administrator"></td></tr>`).join('')
		const checks = (data.checks || []).map((check) => `<li class="severity-${String(check.status || 'WARN').toLowerCase()}"><b>${esc(check.label)}</b><span>${esc(check.message)}</span></li>`).join('')
		const branch = (data.branches || []).find((item) => item.active) || {}
		const states = [['WIEN','Wien'],['NIEDEROESTERREICH','Niederösterreich'],['OBEROESTERREICH','Oberösterreich'],['STEIERMARK','Steiermark'],['TIROL','Tirol'],['KAERNTEN','Kärnten'],['SALZBURG','Salzburg'],['VORARLBERG','Vorarlberg'],['BURGENLAND','Burgenland']]
		return `<section class="bp-panel bp-onboarding"><div class="bp-panel-head"><div><h3>Geführte Ersteinrichtung</h3><p class="bp-muted">Rollen, Ablage und erste Niederlassung werden gemeinsam geprüft. Vorhandene Nextcloud-Benutzer bleiben die führenden Identitäten.</p></div><span class="bp-status ${data.ready ? 'ready' : 'status-error'}">${data.ready ? 'Betriebsbereit' : 'Einrichtung erforderlich'}</span></div><ul class="bp-billing-exceptions">${checks}</ul><form id="onboarding-form" class="bp-form-grid"><section class="bp-field-section bp-span-2"><h3>1. Gruppen und Benutzer</h3><div class="bp-form-grid"><label><span>Fachbenutzer-Gruppe</span><input name="memberGroup" value="${esc(settings.memberGroup || 'Bestatter')}" required></label><label><span>Administrationsgruppen (kommagetrennt)</span><input name="adminGroups" value="${esc((settings.adminGroups || []).join(', '))}" required></label><label class="bp-inline-check bp-span-2"><input type="checkbox" name="createMissingGroups" checked> Fehlende Gruppen nach Bestätigung anlegen</label><label class="bp-inline-check bp-span-2"><input type="checkbox" name="singlePerson"> Einpersonenbetrieb: Administrator zugleich als Fachbenutzer zuordnen</label></div><div class="bp-table-scroll"><table><thead><tr><th>Vorhandener Nextcloud-Benutzer</th><th>Fachbenutzer</th><th>Administrator</th></tr></thead><tbody>${users || '<tr><td colspan="3" class="bp-empty">Keine vorhandenen Nextcloud-Benutzer gefunden. Benutzer werden nicht automatisch angelegt.</td></tr>'}</tbody></table></div></section><section class="bp-field-section bp-span-2"><h3>2. Ablagestruktur</h3><div class="bp-form-grid"><label><span>Arbeitsordner</span><input name="storageRoot" value="${esc(settings.storageRoot || 'Bestatter')}" required></label><label><span>Fallordner</span><input name="casesFolder" value="${esc(settings.casesFolder || 'Fälle')}" required></label><label><span>Vorlagenordner</span><input name="templatesFolder" value="${esc(settings.templatesFolder || 'Vorlagen')}" required></label><label><span>Artikelbilder</span><input name="articleImagesFolder" value="${esc(settings.articleImagesFolder || 'Artikelbilder')}" required></label><label class="bp-span-2"><span>Fall-Unterordner (eine Zeile je Ordner)</span><textarea name="caseSubfolders" rows="6">${esc((settings.caseSubfolders || []).join('\n'))}</textarea></label></div></section><section class="bp-field-section bp-span-2"><h3>3. Erste Niederlassung und Länderprofil</h3><div class="bp-form-grid"><input type="hidden" name="branchId" value="${Number(branch.id || 0)}"><label><span>Technischer Schlüssel</span><input name="branchKey" value="${esc(branch.key || 'HAUPT')}" required></label><label><span>Name</span><input name="branchName" value="${esc(branch.name || 'Hauptniederlassung')}" required></label><label><span>Land</span><select name="countryCode"><option value="DE" ${(branch.countryCode || 'DE') === 'DE' ? 'selected' : ''}>Deutschland</option><option value="AT" ${branch.countryCode === 'AT' ? 'selected' : ''}>Österreich</option></select></label><label><span>Bundesland (bei Österreich)</span><select name="federalState"><option value="">Nicht erforderlich</option>${states.map(([key,label]) => `<option value="${key}" ${branch.federalState === key ? 'selected' : ''}>${label}</option>`).join('')}</select></label><label><span>Straße / Hausnummer</span><input name="branchStreet" value="${esc(branch.street || '')}"></label><label><span>PLZ</span><input name="branchPostalCode" value="${esc(branch.postalCode || '')}"></label><label><span>Ort</span><input name="branchCity" value="${esc(branch.city || '')}"></label><label class="bp-inline-check bp-span-2"><input type="checkbox" name="provisionTemplates" checked> Fehlende Standardvorlagen bereitstellen; kundeneigene Dateien niemals überschreiben</label></div></section><div class="bp-head-actions bp-span-2"><button type="submit" class="bp-primary">Einrichtung speichern und prüfen</button></div></form></section>`
	}

	function bindOnboarding() {
		document.getElementById('onboarding-form')?.addEventListener('submit', async (event) => {
			event.preventDefault(); const form = event.currentTarget; const values = new FormData(form)
			const settingKeys = ['memberGroup','storageRoot','casesFolder','templatesFolder','articleImagesFolder']
			const settings = Object.fromEntries(settingKeys.map((key) => [key, String(values.get(key) || '').trim()]))
			settings.adminGroups = String(values.get('adminGroups') || '').split(',').map((value) => value.trim()).filter(Boolean)
			settings.assistantFolder = state.onboarding?.settings?.assistantFolder || '.Assistenz'; settings.defaultUploadFolder = state.onboarding?.settings?.defaultUploadFolder || '01 Stammdaten'; settings.orderFolder = state.onboarding?.settings?.orderFolder || '02 Auftrag'; settings.authoritiesFolder = state.onboarding?.settings?.authoritiesFolder || '03 Behörden'; settings.billingFolder = state.onboarding?.settings?.billingFolder || '06 Abrechnung'; settings.caseSubfolders = String(values.get('caseSubfolders') || '').split(/\r?\n/).map((value) => value.trim()).filter(Boolean)
			const memberUids = [...root.querySelectorAll('[data-onboarding-member]:checked')].map((input) => input.value); const adminUids = [...root.querySelectorAll('[data-onboarding-admin]:checked')].map((input) => input.value)
			const existingBranch = (state.onboarding?.branches || []).find((item) => Number(item.id) === Number(values.get('branchId') || 0)) || {}
			const branch = { ...existingBranch, id: Number(values.get('branchId') || 0), key: String(values.get('branchKey') || ''), name: String(values.get('branchName') || ''), countryCode: String(values.get('countryCode') || 'DE'), federalState: String(values.get('federalState') || ''), street: String(values.get('branchStreet') || ''), postalCode: String(values.get('branchPostalCode') || ''), city: String(values.get('branchCity') || '') }
			try { state.onboarding = await api(onboardingUrl(), { method: 'POST', feedback: false, loadingLabel: 'Ersteinrichtung wird gespeichert …', body: new URLSearchParams({ configuration: JSON.stringify({ settings, memberUids, adminUids, branch, createMissingGroups: values.has('createMissingGroups'), singlePerson: values.has('singlePerson'), provisionTemplates: values.has('provisionTemplates') }) }) }); notifySuccess('Die Ersteinrichtung ist abgeschlossen und die Betriebsbereitschaft wurde bestätigt.'); globalThis.location.reload() } catch (error) { notifyError(error.message) }
		})
	}

	async function loadBackups() {
		state.backupOperations = await api(backupsUrl(), { feedback: false, loadingLabel: 'Sicherungen werden geprüft …' })
		return state.backupOperations
	}

	function backupRestoreView() {
		const data = state.backupOperations || { items: [], targetEmpty: false, scope: '' }
		const settings = data.settings || { directory: 'bestatter-backups', snapshotRetentionDays: 30, packageRetentionDays: 90 }
		const rows = (data.items || []).map((item) => `<tr><td><b>${esc(item.name)}</b><small>${item.kind === 'PACKAGE' ? 'Vollständiges Fachpaket' : 'Schneller App-Snapshot'} · App-Version ${esc(item.appVersion || 'unbekannt')}</small><small>${item.location === 'LEGACY' ? 'Bisheriger Speicherort' : 'Aktiver Sicherungsordner'}${item.expired ? ' · Aufbewahrungsfrist erreicht' : ''}</small></td><td>${esc(item.createdAt ? new Date(item.createdAt).toLocaleString('de-DE') : new Date(item.modifiedAt).toLocaleString('de-DE'))}<small>${Number(item.ageDays || 0)} Tage alt</small></td><td>${Number(item.size || 0).toLocaleString('de-DE')} Byte${item.kind === 'PACKAGE' ? `<small>${Number(item.fileCount || 0).toLocaleString('de-DE')} Dateien · ${Number(item.totalBytes || 0).toLocaleString('de-DE')} Byte Nutzdaten</small>` : ''}</td><td><span class="bp-status ${item.valid && item.packageStatus !== 'WARN' ? 'ready' : 'status-error'}">${item.valid ? (item.packageStatus === 'WARN' ? 'Unvollständig' : 'Prüfsumme gültig') : 'Ungültig'}</span>${item.error ? `<small class="bp-error-text">${esc(item.error)}</small>` : ''}</td><td><div class="bp-row-actions"><button type="button" class="bp-secondary verify-backup" data-backup-file="${esc(item.name)}">Prüfen</button>${item.valid ? `<button type="button" class="bp-secondary download-backup" data-backup-file="${esc(item.name)}">Speichern unter …</button>` : ''}<button type="button" class="bp-danger delete-backup" data-backup-file="${esc(item.name)}">Löschen</button></div></td></tr>`).join('')
		const restoreState = data.targetEmpty
			? '<span class="bp-status ready">Leeres Ziel erkannt</span>'
			: '<span class="bp-status">Produktivdaten vorhanden – Web-Restore gesperrt</span>'
		return `<section class="bp-panel bp-backup-restore"><div class="bp-panel-head"><div><h3>Backup und Restore</h3><p class="bp-muted">Schnelle Datenbanksnapshots und vollständige Fachpakete kontrolliert erstellen.</p></div><div class="bp-head-actions"><button type="button" class="bp-secondary" id="create-backup">Schnellen App-Snapshot erstellen</button><button type="button" class="bp-primary" id="create-backup-package">Vollständiges Sicherungspaket erstellen</button></div></div><aside class="bp-compliance-note"><b>Vollständiges Fachpaket:</b> App-Datenbank, App-Konfiguration, Fallakten, Dokumentvorlagen und Artikelbilder samt Manifest und Einzelprüfsummen.<span>Für eine vollständige Serverwiederherstellung bleiben zusätzlich Nextcloud-Datenbank, <code>config/</code>, App-Code und Compose-/Secret-Konfiguration zu sichern.</span><span><b>Vertraulich:</b> Sicherungen enthalten personenbezogene Daten und können Integrationsgeheimnisse enthalten.</span></aside><section class="bp-field-section"><div class="bp-panel-head"><div><h3>Serverablage und Aufbewahrung</h3><p class="bp-muted">Der Unterordner liegt immer innerhalb des geschützten Nextcloud-Datenverzeichnisses. Bereits vorhandene Sicherungen im bisherigen Stammverzeichnis bleiben sichtbar.</p></div><button type="button" class="bp-secondary" id="cleanup-backups">Fristabgelaufene Sicherungen löschen</button></div><form id="backup-settings" class="bp-form-grid"><label><span>Sicherungsunterordner</span><input name="directory" value="${esc(settings.directory)}" required><small>Aktuell: ${esc(data.directory || '–')}</small></label><label><span>JSON-Snapshots aufbewahren</span><input type="number" min="0" max="3650" name="snapshotRetentionDays" value="${Number(settings.snapshotRetentionDays)}"><small>Tage; 0 bedeutet unbegrenzt.</small></label><label><span>ZIP-Fachpakete aufbewahren</span><input type="number" min="0" max="3650" name="packageRetentionDays" value="${Number(settings.packageRetentionDays)}"><small>Tage; das letzte gültige Paket bleibt immer geschützt.</small></label><div class="bp-row-actions"><button type="submit" class="bp-primary">Einstellungen speichern</button></div></form></section><div class="bp-table-scroll"><table><thead><tr><th>Sicherung</th><th>Erstellt</th><th>Größe</th><th>Integrität</th><th>Aktionen</th></tr></thead><tbody>${rows || '<tr><td colspan="5" class="bp-empty">Noch keine Sicherung im Nextcloud-Datenverzeichnis vorhanden.</td></tr>'}</tbody></table></div><section class="bp-field-section"><div class="bp-panel-head"><div><h3>Wiederherstellung</h3><p class="bp-muted">Restore ist absichtlich kein Ein-Klick-Vorgang und nur in einer leeren, isolierten Zielinstallation zulässig.</p></div>${restoreState}</div><ul><li><b>JSON-Schnellsnapshot:</b> stellt ausschließlich App-Datenbank und App-Konfiguration wieder her.</li><li><b>ZIP-Fachpaket:</b> stellt zusätzlich Fallakten, Vorlagen und Artikelbilder wieder her und ist für die fachliche Wiederherstellung zu bevorzugen.</li></ul><ol><li>Sicherung prüfen und eine externe, verschlüsselte Kopie ablegen.</li><li>Leere Zielinstallation mit passender App-Version bereitstellen.</li><li><code>php occ bestatter:restore /absoluter/pfad/sicherung.zip</code> zur Vorschau ausführen.</li><li>Mit <code>--execute --confirmation=BESTATTER-RESTORE-LEERES-ZIEL</code> wiederherstellen und anschließend die Abnahmeprüfung starten.</li></ol></section><section class="bp-field-section"><h3>Deinstallation und endgültige Bereinigung</h3><p>Das Deaktivieren oder Entfernen des App-Codes löscht keine Fachdaten. Der ausschließlich administrative Befehl <code>php occ bestatter:purge</code> zeigt zunächst alle Ziele an. Eine Ausführung verlangt ein zuvor geprüftes vollständiges Sicherungspaket, eine bestandene Legal-Hold-Prüfung und den angezeigten Bestätigungscode.</p><p class="bp-warning">Benutzer, Gruppen, Sicherungspakete und externe Paperless-Originale bleiben erhalten.</p></section></section>`
	}

	function bindBackupRestore() {
		document.getElementById('backup-settings')?.addEventListener('submit', async (event) => {
			event.preventDefault(); const values = new FormData(event.currentTarget)
			try { await api(`${backupsUrl()}/settings`, { method: 'PUT', body: new URLSearchParams({ settings: JSON.stringify({ directory: values.get('directory'), snapshotRetentionDays: Number(values.get('snapshotRetentionDays')), packageRetentionDays: Number(values.get('packageRetentionDays')) }) }), feedback: false, loadingLabel: 'Sicherungseinstellungen werden gespeichert …' }); notifySuccess('Sicherungsordner und Aufbewahrungsfristen wurden gespeichert.'); await loadBackups(); render() } catch (error) { notifyError(error.message) }
		})
		document.getElementById('cleanup-backups')?.addEventListener('click', async () => {
			const expired = (state.backupOperations?.items || []).filter((item) => item.expired).length
			if (!expired) { notifyWarning('Nach den eingestellten Fristen sind derzeit keine Sicherungen zu löschen.'); return }
			if (!await confirmAction(`${expired} fristabgelaufene Sicherung(en) einschließlich zugehöriger Prüfsummendateien löschen? Das letzte gültige vollständige Fachpaket bleibt geschützt.`, { title: 'Alte Sicherungen bereinigen', confirmLabel: 'Fristabgelaufene löschen', danger: true })) return
			try { const result = await api(`${backupsUrl()}/cleanup`, { method: 'POST', feedback: false, loadingLabel: 'Alte Sicherungen werden bereinigt …' }); notifySuccess(`${result.deleted?.length || 0} Sicherung(en) wurden gelöscht.${result.skipped?.length ? ` ${result.skipped.length} blieben aus Sicherheitsgründen erhalten.` : ''}`); await loadBackups(); render() } catch (error) { notifyError(error.message) }
		})
		document.getElementById('create-backup')?.addEventListener('click', async () => {
			try {
				const result = await api(backupsUrl(), { method: 'POST', feedback: false, loadingLabel: 'App-Snapshot wird erstellt …' })
				notifySuccess(`App-Snapshot ${String(result.path || '').split(/[\\/]/).pop() || ''} wurde erstellt und mit Prüfsumme protokolliert.`)
				await loadBackups(); render()
			} catch (error) { notifyError(error.message) }
		})
		document.getElementById('create-backup-package')?.addEventListener('click', async () => {
			try { const result = await api(backupsUrl(), { method: 'POST', body: new URLSearchParams({ includeFiles: 'true' }), feedback: false, loadingLabel: 'Vollständiges Sicherungspaket wird erstellt …' }); if (result.status === 'WARN') notifyError(`Das Paket wurde mit ${result.errors?.length || 0} Dateifehlern erstellt und darf nicht für Restore oder Purge verwendet werden.`); else notifySuccess(`Sicherungspaket mit ${Number(result.fileCount || 0).toLocaleString('de-DE')} Dateien wurde erstellt und geprüft.`); await loadBackups(); render() } catch (error) { notifyError(error.message) }
		})
		root.querySelectorAll('.verify-backup').forEach((button) => button.addEventListener('click', async () => {
			try {
				const result = await api(`${backupsUrl()}/${encodeURIComponent(button.dataset.backupFile)}/verify`, { method: 'POST', feedback: false, loadingLabel: 'Sicherung wird geprüft …' })
				notifySuccess(`Sicherung ist gültig: ${Number(Object.values(result.tables || {}).reduce((sum, count) => sum + Number(count || 0), 0)).toLocaleString('de-DE')} Datensätze, App-Version ${result.appVersion || 'unbekannt'}.`)
			} catch (error) { notifyError(error.message) }
		}))
		root.querySelectorAll('.download-backup').forEach((button) => button.addEventListener('click', async () => {
			try { const saved = await download(`${backupsUrl()}/${encodeURIComponent(button.dataset.backupFile)}/download`, button.dataset.backupFile, { saveAs: true, description: 'Bestatter-Sicherung' }); if (saved) notifySuccess(`${saved} wurde am ausgewählten Ort gespeichert.`) }
			catch (error) { notifyError(error.message) }
		}))
		root.querySelectorAll('.delete-backup').forEach((button) => button.addEventListener('click', async () => {
			const name = button.dataset.backupFile
			if (!await confirmAction(`Die Sicherung „${name}“ und ihre Prüfsummendatei endgültig vom Server löschen?`, { title: 'Sicherung löschen', confirmLabel: 'Endgültig löschen', danger: true })) return
			try { await api(`${backupsUrl()}/${encodeURIComponent(name)}`, { method: 'DELETE', feedback: false, loadingLabel: 'Sicherung wird gelöscht …' }); notifySuccess(`${name} wurde gelöscht.`); await loadBackups(); render() } catch (error) { notifyError(error.message) }
		}))
	}

	async function loadOperationsCockpit() {
		state.operationsCockpit = await api(cockpitUrl(), { feedback: false, loadingLabel: 'Betriebs-Cockpit wird aktualisiert …' })
		return state.operationsCockpit
	}

	function operationsCockpitView() {
		const report = state.operationsCockpit
		if (!report) return '<section class="bp-panel"><p class="bp-empty">Das Betriebs-Cockpit wurde noch nicht geladen.</p><button class="bp-primary" id="refresh-operations-cockpit">Jetzt laden</button></section>'
		const summary = report.summary || {}
		const statusLabels = { OK: 'Betrieb unauffällig', WARN: 'Hinweise vorhanden', ERROR: 'Handlungsbedarf' }
		const cards = [
			['Fehlgeschlagene Workflows', summary.failedWorkflows, 'workflow', 'Systemprüfung öffnen'],
			['Offene Paperless-Jobs', summary.openPaperlessJobs, 'paperless', 'Paperless öffnen'],
			['Fehlgeschlagene Paperless-Jobs', summary.failedPaperlessJobs, 'paperless', 'Paperless öffnen'],
			['Nicht zugeordnete Dokumente', summary.unassignedPaperlessDocuments, 'inbox', 'Dokumenteingang öffnen'],
			['Aufbewahrung fällig', summary.retentionDue, 'retention', 'Aufbewahrung öffnen'],
			['Abgeschlossene Fälle mit offenen Nebenaufträgen', summary.inconsistentSideOrderCases, 'cockpit', 'Details unten prüfen'],
		]
		const workflowRows = (report.workflowRuns?.items || []).map((item) => `<tr><td>${esc(item.createdAt ? new Date(item.createdAt).toLocaleString('de-DE') : '–')}</td><td>${esc(item.caseNumber || 'ohne Fallbezug')}</td><td>${esc(item.sourceTitle || item.actionKey)}</td><td class="bp-error-text">${esc(item.error)}</td><td>${item.caseId ? `<button type="button" class="bp-secondary cockpit-open-case" data-case-id="${Number(item.caseId)}">Fall öffnen</button>` : '–'}</td></tr>`).join('')
		const paperlessRows = (report.paperless?.items || []).map((item) => `<tr><td>${esc(item.status)}</td><td>${esc(item.operation)}</td><td>${esc(item.caseNumber || 'nicht zugeordnet')}</td><td>${esc(item.title || item.externalDocumentId || '–')}</td><td>${Number(item.attempts || 0)}</td><td class="bp-error-text">${esc(item.error || '–')}</td><td>${item.caseId ? `<button type="button" class="bp-secondary cockpit-open-case" data-case-id="${Number(item.caseId)}">Fall öffnen</button>` : `<button type="button" class="bp-secondary cockpit-target" data-target="inbox">Eingang öffnen</button>`}</td></tr>`).join('')
		const retentionRows = (report.retention?.items || []).map((item) => `<tr><td>${esc(item.caseNumber || '–')}</td><td>${esc(item.lastChanged || '–')}</td><td>${esc(item.individualDueDate || report.retention.cutoff || '–')}</td><td>${item.id ? `<button type="button" class="bp-secondary cockpit-open-case" data-case-id="${Number(item.id)}">Fall öffnen</button>` : '–'}</td></tr>`).join('')
		const inconsistentRows = (report.inconsistentSideOrderCases?.items || []).map((item) => `<tr><td>${esc(item.caseNumber)}</td><td>${esc(item.sideOrderNumber)}</td><td>${esc(item.status)}</td><td><button type="button" class="bp-secondary cockpit-open-case" data-case-id="${Number(item.id)}">Fall öffnen</button></td></tr>`).join('')
		const maintenance = report.maintenance || {}
		return `<section class="bp-panel bp-operations-cockpit"><div class="bp-panel-head"><div><h3>Betriebs-Cockpit</h3><p class="bp-muted">Zentrale, rein lesende Übersicht über technische und organisatorische Ausnahmefälle.</p></div><button type="button" class="bp-primary" id="refresh-operations-cockpit">Aktualisieren</button></div><div class="bp-system-summary status-${String(report.overall || 'WARN').toLowerCase()}"><b>${esc(statusLabels[report.overall] || report.overall)}</b><span>Stand ${esc(report.generatedAt ? new Date(report.generatedAt).toLocaleString('de-DE') : '–')}</span></div><div class="bp-cockpit-grid">${cards.map(([label, value, target, action]) => `<article class="bp-cockpit-card ${Number(value || 0) > 0 ? 'has-items' : ''}"><p class="bp-eyebrow">${esc(label)}</p><strong>${Number(value || 0)}</strong><button type="button" class="bp-secondary cockpit-target" data-target="${target}">${esc(action)}</button></article>`).join('')}<article class="bp-cockpit-card ${maintenance.stale || maintenance.status !== 'OK' ? 'has-items' : ''}"><p class="bp-eyebrow">Wartungsjob</p><strong>${maintenance.stale ? 'Überfällig' : esc(maintenance.status || 'Unbekannt')}</strong><p>${maintenance.lastRun ? `Zuletzt ${esc(new Date(maintenance.lastRun).toLocaleString('de-DE'))}` : 'Noch kein Lauf dokumentiert.'}</p><button type="button" class="bp-secondary cockpit-target" data-target="system">Systemprüfung öffnen</button></article></div><details open><summary>Fehlgeschlagene Workflow-Läufe (${Number(summary.failedWorkflows || 0)})</summary><div class="bp-table-scroll"><table><thead><tr><th>Zeitpunkt</th><th>Fall</th><th>Aktion</th><th>Fehler</th><th></th></tr></thead><tbody>${workflowRows || '<tr><td colspan="5" class="bp-empty">Keine fehlgeschlagenen Workflow-Läufe.</td></tr>'}</tbody></table></div></details><details><summary>Offene und fehlgeschlagene Paperless-Jobs</summary><div class="bp-table-scroll"><table><thead><tr><th>Status</th><th>Vorgang</th><th>Fall</th><th>Dokument</th><th>Versuche</th><th>Fehler</th><th></th></tr></thead><tbody>${paperlessRows || '<tr><td colspan="7" class="bp-empty">Keine offenen Paperless-Jobs.</td></tr>'}</tbody></table></div></details><details ${inconsistentRows?'open':''}><summary>Abgeschlossene Fälle mit offenen Nebenaufträgen (${Number(summary.inconsistentSideOrderCases || 0)})</summary><p class="bp-muted">Rein lesende Diagnose; es erfolgt keine automatische Statusänderung.</p><div class="bp-table-scroll"><table><thead><tr><th>Fall</th><th>Nebenauftrag</th><th>Status</th><th></th></tr></thead><tbody>${inconsistentRows || '<tr><td colspan="4" class="bp-empty">Keine widersprüchlichen Fallzustände.</td></tr>'}</tbody></table></div></details><details><summary>Fällige Aufbewahrungsfälle (${Number(summary.retentionDue || 0)})</summary><p class="bp-muted">Diese Liste ist eine Vorschau. Das Cockpit löscht und anonymisiert keine Daten.</p><div class="bp-table-scroll"><table><thead><tr><th>Fall</th><th>Abgeschlossen</th><th>Fällig / Stichtag</th><th></th></tr></thead><tbody>${retentionRows || '<tr><td colspan="4" class="bp-empty">Keine fälligen Fälle.</td></tr>'}</tbody></table></div></details></section>`
	}

	function bindOperationsCockpit() {
		document.getElementById('refresh-operations-cockpit')?.addEventListener('click', async () => { try { await loadOperationsCockpit(); render() } catch (error) { notifyError(error.message) } })
		root.querySelectorAll('.cockpit-open-case').forEach((button) => button.addEventListener('click', async () => {
			try { state.currentCase = await api(`${ctx.urls.cases}/${button.dataset.caseId}`, { feedback: false }); state.currentCaseId = Number(button.dataset.caseId); state.view = 'case-detail'; state.caseTab = 'overview'; render() } catch (error) { notifyError(error.message) }
		}))
		root.querySelectorAll('.cockpit-target').forEach((button) => button.addEventListener('click', async () => {
			try {
				const target = button.dataset.target
				if (target === 'cockpit') { [...(button.closest('.bp-operations-cockpit')?.querySelectorAll('details') || [])].find((entry)=>entry.textContent.includes('Abgeschlossene Fälle mit offenen Nebenaufträgen'))?.scrollIntoView({ behavior: 'smooth', block: 'start' }); return }
				if (target === 'inbox') { state.view = 'inbox'; await ctx.loadPaperlessInbox(); render(); return }
				state.view = 'administration'
				state.administrationTab = target === 'paperless' ? 'paperless' : 'system'
				if (target === 'paperless') await ctx.loadPaperlessConfiguration()
				else await loadSystemCheck()
				render()
			} catch (error) { notifyError(error.message) }
		}))
	}

	async function loadSystemCheck() {
		const [report, installation, retention, retentionPreview, auditIntegrity] = await Promise.all([api(systemCheckUrl(), { feedback: false, loadingLabel: 'Systemprüfung wird ausgeführt …' }), api(installationSettingsUrl(), { feedback: false }), api(retentionUrl(), {feedback:false}), api(`${retentionUrl()}/preview`, {feedback:false}), api(`${ctx.apiBase}/operations/audit-integrity`, {feedback:false})])
		state.systemCheck = report
		state.installationSettings = installation
		state.retentionPolicy = retention
		state.retentionPreview = retentionPreview
		state.auditIntegrity = auditIntegrity
		return state.systemCheck
	}

	async function loadReportingSummary() {
		const filters=state.reportFilters||{from:'',to:'',branch:'ALL'}
		const query=new URLSearchParams(filters)
		state.reportSummary=await api(`${reportSummaryUrl()}?${query}`,{feedback:false,loadingLabel:'Auswertungen werden vorbereitet …'})
		return state.reportSummary
	}

	function reportingView() {
		const filters=state.reportFilters||{from:'',to:'',branch:'ALL'}; const summary=state.reportSummary||{}; const kpis=summary.kpis||{}; const active=state.reportingSection||'overview'
		const branches=(state.branches||[]).filter((entry)=>entry.active).map((entry)=>`<option value="${esc(entry.key)}" ${filters.branch===entry.key?'selected':''}>${esc(entry.name)}</option>`).join('')
		const generatedIndicators=(kpis.generatedIndicators||[]).filter((item)=>item.Wert!==''&&item.Wert!==null&&item.Wert!==undefined)
		const reports=[['cases','Fallübersicht','Fälle',summary.cases,'Fallnummer, Person, Status, Bestattungsart und Zuständigkeit.'],['services','Leistungsstatus','Positionen',summary.services,'Beauftragte, erbrachte und fakturierte Mengen mit Abrechenbarkeit.'],['invoices','Rechnungen bis Ausgabe','Rechnungen',summary.invoices,'Rechnungsstatus und Summen; ohne Zahlungsüberwachung oder Mahnwesen.'],['branches','Rechnungsvolumen je Niederlassung','Niederlassungen',summary.branches,'Nicht stornierte Rechnungsbeträge nach Niederlassung, bis zur Rechnungsstellung.'],['workload','Planbelastung je Mitarbeiter','Aktivitäten',summary.workload,'Planzeit und dokumentierte Istzeit; keine Auslastungsquote ohne Dienstpläne.'],['indicators','Kennzahlenbericht','Kennzahlen',generatedIndicators.length,'Berechenbare Plan-/Ist-, Prozess-, Frist- und Leistungsstruktur-KPIs mit Qualitätsstatus.']]
		const navigation=[['overview','Übersicht'],['employees','Mitarbeiter & Zeit'],['operations','Fälle & Leistungen'],['finance','Finanzen'],['indicators','Kennzahlenbericht'],['exports','CSV-Exporte']].map(([key,label])=>`<button type="button" class="${active===key?'active':''}" data-report-section="${key}">${label}</button>`).join('')
		const qualityChecks=kpis.quality?.checks||[]; const qualityByKey=Object.fromEntries(qualityChecks.map((item)=>[item.key,item])); const qualityLabel=(status)=>({OK:'Plausibel',WARN:'Hinweis',ERROR:'Prüfen',NOT_AVAILABLE:'Nicht verfügbar'}[status]||status); const qualityBadge=(key)=>{const item=qualityByKey[key];return item?`<span class="bp-kpi-quality status-${String(item.status).toLowerCase()}" title="${esc(item.message)}">${esc(qualityLabel(item.status))}</span>`:''}; const display=(value,empty='–')=>value===null||value===undefined||value===''?empty:value
		const cards=(items)=>`<div class="bp-report-grid">${items.map(([label,value,description,key])=>`<article><p class="bp-eyebrow">${esc(label)} ${qualityBadge(key)}</p><strong>${esc(value)}</strong><p>${esc(description)}</p></article>`).join('')}</div>`
		const hours=(minutes)=>`${(Number(minutes||0)/60).toLocaleString('de-DE',{minimumFractionDigits:1,maximumFractionDigits:1})} Std.`
		const employeeRows=(kpis.employees||[]).map((item)=>`<tr><td>${esc(item.name)}</td><td>${Number(item.openTasks||0)}</td><td>${Number(item.completedTasks||0)}</td><td>${Number(item.overdueTasks||0)}</td><td>${Number(item.appointments||0)}</td><td>${esc(hours(item.plannedMinutes))}</td><td>${Number(item.actualMinutes||0)>0?esc(hours(item.actualMinutes)):'–'}</td><td>${Number(item.actualTimeCoveragePercent||0).toLocaleString('de-DE')} %</td></tr>`).join('')
		const indicatorStatusLabel=(status)=>({BELASTBAR:'Belastbar',BERECHNET:'Berechnet',EINGESCHRAENKT:'Eingeschränkte Datenbasis'}[status]||status)
		const indicatorRows=generatedIndicators.map((item)=>`<tr><td><b>${esc(item.Kennzahl)}</b></td><td class="number"><b>${Number(item.Wert).toLocaleString('de-DE',{maximumFractionDigits:2})} ${esc(item.Einheit||'')}</b>${item['Bezugswert netto EUR']!==''?`<small>${Number(item['Bezugswert netto EUR']).toLocaleString('de-DE',{minimumFractionDigits:2,maximumFractionDigits:2})} EUR netto</small>`:''}</td><td><span class="bp-kpi-quality status-${item.Status==='EINGESCHRAENKT'?'warn':'ok'}">${esc(indicatorStatusLabel(item.Status))}</span></td><td>${esc(item['Datenbasis / Einschränkung']||'')}</td></tr>`).join('')
		const qualityView=`<section class="bp-compliance-note"><h3>Datenqualität und Plausibilität</h3><p>Die Kennzahlen werden nur so belastbar wie die zugrunde liegenden Erfassungen. Die Prüfung ersetzt keine fachliche Kontrolle.</p><ul class="bp-report-quality">${qualityChecks.map((item)=>`<li class="status-${String(item.status).toLowerCase()}"><b>${esc(item.label)}: ${esc(qualityLabel(item.status))}</b><span>${esc(item.message)}${item.coveragePercent!==null&&item.coveragePercent!==undefined?` (${Number(item.coveragePercent).toLocaleString('de-DE')} % Abdeckung)`:''}</span></li>`).join('')}</ul></section>`
		const sections={overview:`${cards([['Offene Fälle',Number(kpis.openCases||0),'Aktive Fälle im ausgewählten Zeitraum.'],['Offene Aufgaben',Number(kpis.openTasks||0),'Noch nicht erledigte Aufgaben.'],['Überfällige Aufgaben',Number(kpis.overdueTasks||0),'Fälligkeit liegt vor dem aktuellen Zeitpunkt.'],['Termine',Number(kpis.appointments||0),'Interne und externe Termine im Zeitraum.'],['Planbelastung',hours(kpis.plannedMinutes),'Disposition aus Termindauern und Aufgabenschätzungen.','planned_time'],['Istzeit-Abdeckung',`${Number(kpis.actualTimeCoveragePercent||0).toLocaleString('de-DE')} %`,'Anteil der Aktivitäten mit dokumentierter Istzeit.','actual_time'],['Rechnungsvolumen',formatMoney(Math.round(Number(kpis.invoiceGross||0)*100)),'Nicht stornierte Rechnungen bis zur Ausgabe.','invoices']])}${qualityView}`,employees:`<section><h3>Planbelastung und Zeiteinsatz</h3><p class="bp-muted">Die Tabelle zeigt Planbelastung. Eine echte Auslastungsquote bleibt ohne Dienstpläne und Kapazitätsdaten bewusst deaktiviert.</p><div class="bp-table-scroll"><table class="bp-report-table"><thead><tr><th>Mitarbeiter/in</th><th>Offen</th><th>Erledigt</th><th>Überfällig</th><th>Termine</th><th>Planzeit</th><th>Ist-Zeit</th><th>Istzeit-Abdeckung</th></tr></thead><tbody>${employeeRows||'<tr><td colspan="8">Keine Aktivitäten im Zeitraum.</td></tr>'}</tbody></table></div></section>${qualityView}`,operations:`${cards([['Fälle',Number(summary.cases||0),'Angelegte Fälle im Filterzeitraum.'],['Leistungspositionen',Number(summary.services||0),'Beauftragte Fallleistungen.'],['Erbrachte Positionen',Number(kpis.performedServices||0),'Positionen mit erfasster Leistungsmenge.'],['Leistungserbringungsgrad',display(kpis.serviceCompletionRate)!== '–' ? `${Number(kpis.serviceCompletionRate).toLocaleString('de-DE')} %` : '–','Erbracht im Verhältnis zur beauftragten Menge.','services'],['Fakturierungsgrad',display(kpis.billingRate)!== '–' ? `${Number(kpis.billingRate).toLocaleString('de-DE')} %` : '–','Fakturiert im Verhältnis zur erbrachten Menge.','services']])}${qualityView}`,finance:`${cards([['Rechnungen',Number(summary.invoices||0),'Erstellte Teil- und Schlussrechnungen.'],['Rechnungsvolumen',formatMoney(Math.round(Number(kpis.invoiceGross||0)*100)),'Bruttosumme ohne stornierte Rechnungen.','invoices'],['Freigegebenes Volumen',formatMoney(Math.round(Number(kpis.committedInvoiceGross||0)*100)),'Ausgegebene Rechnungen ohne Zahlungsüberwachung.','invoices'],['Durchschnittliche Rechnung',kpis.averageInvoiceGross===null?'–':formatMoney(Math.round(Number(kpis.averageInvoiceGross)*100)),'Durchschnittliches Brutto nicht stornierter Rechnungen.','invoices'],['Niederlassungen',Number(summary.branches||0),'Niederlassungen mit Rechnungsbewegung.']])}${qualityView}<p class="bp-compliance-note"><b>Abgrenzung:</b> Zahlungseingänge, Mahnwesen, Storno und Gutschriften bleiben gemäß Fachkonzept OP-Themen.</p>`,indicators:`<section><div class="bp-panel-head"><div><h3>Kennzahlenbericht</h3><p class="bp-muted">Nur bereits berechenbare Kennzahlen im gewählten Zeitraum. Konzeptionelle oder noch nicht konfigurierte Kennzahlen werden nicht als Ergebnis angezeigt.</p></div><button type="button" class="bp-secondary download-report" data-report="indicators">CSV herunterladen</button></div><div class="bp-table-scroll"><table class="bp-report-table"><thead><tr><th>Kennzahl</th><th>Wert</th><th>Datenqualität</th><th>Berechnungsgrundlage</th></tr></thead><tbody>${indicatorRows||'<tr><td colspan="4" class="bp-empty">Für den gewählten Zeitraum sind noch keine Kennzahlen berechenbar.</td></tr>'}</tbody></table></div></section>${qualityView}`,exports:`<section><h3>CSV-Auswertungen</h3><p class="bp-muted">Datensparsame Übergabe an Buchhaltung und interne Steuerung. Jeder Download wird im Audit-Protokoll dokumentiert.</p><div class="bp-report-grid">${reports.map(([key,title,countLabel,count,description])=>`<article><p class="bp-eyebrow">${esc(countLabel)}</p><strong>${Number(count||0)}</strong><h4>${esc(title)}</h4><p>${esc(description)}</p><button type="button" class="bp-secondary download-report" data-report="${key}">CSV herunterladen</button></article>`).join('')}</div></section>`}
		return `<section class="bp-panel bp-reporting"><div class="bp-panel-head"><div><h3>Kennzahlen und Auswertungen</h3><p class="bp-muted">Operative Steuerung bis einschließlich Rechnungsstellung. Filter gelten für alle Ansichten und Exporte.</p></div><button type="button" class="bp-secondary" id="refresh-reports">Zahlen aktualisieren</button></div><form id="report-filters" class="bp-form-grid"><label><span>Von</span><input type="date" name="from" value="${esc(filters.from)}"></label><label><span>Bis</span><input type="date" name="to" value="${esc(filters.to)}"></label><label><span>Niederlassung</span><select name="branch"><option value="ALL">Alle Niederlassungen</option>${branches}</select></label><div class="bp-row-actions"><button class="bp-primary">Filter anwenden</button></div></form><nav class="bp-report-nav" aria-label="Kennzahlenbereiche">${navigation}</nav>${sections[active]||sections.overview}<aside class="bp-compliance-note"><b>Datenschutz:</b> Bankdaten, interne Fallnotizen, Kontaktdetails und Gesundheitsangaben werden in den Standardexporten nicht ausgegeben.</aside></section>`
	}

	function bindReporting() {
		const apply=async()=>{const form=document.getElementById('report-filters');if(form)state.reportFilters=Object.fromEntries(new FormData(form));await loadReportingSummary();render()}
		document.getElementById('report-filters')?.addEventListener('submit',async(event)=>{event.preventDefault();try{await apply()}catch(error){notifyError(error.message)}})
		document.getElementById('refresh-reports')?.addEventListener('click',async()=>{try{await apply()}catch(error){notifyError(error.message)}})
		root.querySelectorAll('.download-report').forEach((button)=>button.addEventListener('click',async()=>{const filters=state.reportFilters||{from:'',to:'',branch:'ALL'};const query=new URLSearchParams(filters);try{await download(`${ctx.apiBase}/reports/${button.dataset.report}.csv?${query}`,`Bestatter-${button.dataset.report}.csv`)}catch(error){notifyError(error.message)}}))
		root.querySelectorAll('[data-report-section]').forEach((button)=>button.addEventListener('click',()=>{state.reportingSection=button.dataset.reportSection;render()}))
	}

	function installationSettingsView() {
		const s=state.installationSettings; if(!s)return ''
		const folderOptions=(selected)=>(s.caseSubfolders||[]).map(name=>`<option ${name===selected?'selected':''}>${esc(name)}</option>`).join('')
		return `<section class="bp-panel bp-config-admin"><div class="bp-panel-head"><div><h3>Installationsparameter</h3><p class="bp-muted">Gruppen und benutzerbezogene Nextcloud-Ablagen zentral und updatefest konfigurieren.</p></div><span class="bp-save-state" id="installation-settings-state">Änderungen verschieben keine vorhandenen Dateien.</span></div><form id="installation-settings" class="bp-form-grid"><label><span>Bestatter-Mitgliedergruppe</span><input name="memberGroup" value="${esc(s.memberGroup)}" required></label><label><span>Administrationsgruppen</span><input name="adminGroups" value="${esc((s.adminGroups||[]).join(', '))}" required><small>Mehrere Gruppen durch Komma trennen.</small></label><label class="bp-span-2"><span>Arbeitsordner relativ zum Benutzerordner</span><input name="storageRoot" value="${esc(s.storageRoot)}" required><small>Zum Beispiel Bestatter oder Unternehmen/Bestatter.</small></label><label><span>Fallaktenordner</span><input name="casesFolder" value="${esc(s.casesFolder)}" required></label><label><span>Vorlagenordner</span><input name="templatesFolder" value="${esc(s.templatesFolder)}" required></label><label><span>Temporärer Assistenzordner</span><input name="assistantFolder" value="${esc(s.assistantFolder)}" required></label><label><span>Artikelbilderordner</span><input name="articleImagesFolder" value="${esc(s.articleImagesFolder)}" required></label><label class="bp-span-2"><span>Standard-Unterordner der Fallakte (einer pro Zeile)</span><textarea name="caseSubfolders" rows="5" required>${esc((s.caseSubfolders||[]).join('\n'))}</textarea></label><label><span>Standardablage Upload</span><select name="defaultUploadFolder">${folderOptions(s.defaultUploadFolder)}</select></label><label><span>Ablage Auftrag/KVA</span><select name="orderFolder">${folderOptions(s.orderFolder)}</select></label><label><span>Ablage Behörden</span><select name="authoritiesFolder">${folderOptions(s.authoritiesFolder)}</select></label><label><span>Ablage Rechnungen</span><select name="billingFolder">${folderOptions(s.billingFolder)}</select></label><aside class="bp-compliance-note bp-span-2"><b>Bestehende Installation:</b> Vor einer Pfadänderung vorhandene Ordner administrativ an den neuen Ort verschieben. Dokumentvorlagen müssen auf einen der konfigurierten Fall-Unterordner zeigen.</aside><div class="bp-span-2 bp-row-actions"><button class="bp-primary">Installationsparameter speichern</button></div></form></section>`
	}

	function bindInstallationSettings(){const form=document.getElementById('installation-settings');if(!form)return;form.addEventListener('submit',async(event)=>{event.preventDefault();const status=document.getElementById('installation-settings-state');const values=Object.fromEntries(new FormData(form));values.adminGroups=String(values.adminGroups||'').split(',').map(v=>v.trim()).filter(Boolean);values.caseSubfolders=String(values.caseSubfolders||'').split(/\r?\n/).map(v=>v.trim()).filter(Boolean);try{state.installationSettings=await api(installationSettingsUrl(),{method:'PUT',feedback:false,body:new URLSearchParams({settings:JSON.stringify(values)})});status.textContent='Gespeichert. Systemprüfung bitte erneut starten.';status.dataset.state='saved'}catch(error){status.textContent=error.message;status.dataset.state='error'}})}

	function operationsReadinessView() {
		const policy=state.retentionPolicy||{}; const preview=state.retentionPreview||{count:0,cases:[]}; const audit=state.auditIntegrity||{}
		return `<section class="bp-panel"><div class="bp-panel-head"><div><h3>Datenschutz und Betriebsverfahren</h3><p class="bp-muted">Aufbewahrungsprüfung, Fall-Export, Audit-Integrität und Wiederherstellungsverfahren.</p></div><span class="bp-status ${audit.status==='OK'?'ready':''}">Audit: ${esc(audit.status||'nicht geprüft')}</span></div><form id="retention-policy" class="bp-form-grid"><label class="bp-inline-check"><input type="checkbox" name="enabled" ${policy.enabled?'checked':''}> Aufbewahrungsprüfung aktivieren</label><label><span>Regelfrist nach Abschluss</span><input type="number" name="years" min="1" max="30" value="${Number(policy.years||10)}"><small>Jahre; rechtlich durch den Betreiber festzulegen.</small></label><label><span>Aktion nach Fristablauf</span><select name="mode"><option value="ANONYMIZE" ${policy.mode==='ANONYMIZE'?'selected':''}>Anonymisieren</option><option value="DELETE" ${policy.mode==='DELETE'?'selected':''}>Vollständig löschen</option></select></label><div class="bp-row-actions"><button class="bp-primary">Richtlinie speichern</button></div></form><aside class="bp-compliance-note"><b>Sicherheitsprinzip:</b> Der Hintergrundjob ermittelt nur fällige Fälle. Eine Verarbeitung erfolgt ausschließlich per OCC mit Bestätigungscode und nach geprüftem Backup.</aside><div class="bp-report-grid"><article><p class="bp-eyebrow">Fällige Fälle</p><strong>${Number(preview.count||0)}</strong><p>Ohne gesetzte Aufbewahrungssperre. Vorschau verändert keine Daten.</p></article><article><p class="bp-eyebrow">Audit-Verkettung</p><strong>${Number(audit.checked||0)}</strong><p>${audit.status==='OK'?'Geprüfte Einträge ohne erkannten Kettenbruch.':`${(audit.brokenIds||[]).length} Auffälligkeiten prüfen.`}</p></article><article><p class="bp-eyebrow">Betrieb</p><strong>OCC</strong><p><code>bestatter:backup</code>, <code>bestatter:restore</code> und <code>bestatter:retention</code>. Details im Betriebshandbuch.</p></article></div></section>`
	}

	function bindRetentionPolicy(){const form=document.getElementById('retention-policy');if(!form)return;form.addEventListener('submit',async(event)=>{event.preventDefault();const settings={enabled:form.elements.enabled.checked,years:Number(form.elements.years.value),mode:form.elements.mode.value};try{state.retentionPolicy=await api(retentionUrl(),{method:'PUT',feedback:false,body:new URLSearchParams({settings:JSON.stringify(settings)})});state.retentionPreview=await api(`${retentionUrl()}/preview`,{feedback:false});notifySuccess('Aufbewahrungsrichtlinie gespeichert. Es wurden keine Falldaten verändert.');render()}catch(error){notifyError(error.message)}})}

	function systemCheckView() {
		const report = state.systemCheck
		if (!report) return '<section class="bp-panel"><p class="bp-empty">Die Systemprüfung wurde noch nicht ausgeführt.</p><button class="bp-primary" id="run-system-check">Systemprüfung starten</button></section>'
		const statusLabels = { OK: 'In Ordnung', WARN: 'Hinweis', ERROR: 'Fehler' }
		const checks = (report.checks || []).map((check) => {
			const details = (check.details || []).length ? `<details class="bp-system-details"><summary>Technische Details anzeigen</summary><ul>${check.details.map((item) => `<li>${esc(item)}</li>`).join('')}</ul></details>` : ''
			const action = check.action?.view ? `<button type="button" class="bp-secondary bp-system-action" data-system-view="${esc(check.action.view)}" data-system-tab="${esc(check.action.tab || '')}">${esc(check.action.label || 'Bereich öffnen')}</button>` : ''
			return `<article class="bp-system-check status-${esc(check.status).toLowerCase()}"><span class="bp-system-check-icon" aria-hidden="true">${check.status === 'OK' ? '✓' : (check.status === 'WARN' ? '!' : '×')}</span><div><h3>${esc(check.label)}</h3><p>${esc(check.message)}</p>${check.hint ? `<p class="bp-system-check-hint"><b>Einordnung:</b> ${esc(check.hint)}</p>` : ''}${details}${action}</div><strong>${esc(statusLabels[check.status] || check.status)}</strong></article>`
		}).join('')
		return `<section class="bp-panel bp-system-report"><div class="bp-panel-head"><div><h3>Abnahme- und Systemprüfung</h3><p class="bp-muted">Rein lesende Prüfung für Version ${esc(report.version)} · Stand ${new Date(report.generatedAt).toLocaleString('de-DE')}.</p></div><button class="bp-primary" id="run-system-check">Erneut prüfen</button></div><div class="bp-system-summary status-${esc(report.overall).toLowerCase()}"><b>Gesamtergebnis: ${esc(statusLabels[report.overall] || report.overall)}</b><span>${Number(report.summary?.ok || 0)} in Ordnung · ${Number(report.summary?.warnings || 0)} Hinweise · ${Number(report.summary?.errors || 0)} Fehler</span></div><div class="bp-system-checks">${checks}</div><p class="bp-muted">Die Prüfung versendet keine E-Mails und verändert keine Fall-, Aufgaben- oder Termindaten.</p></section>`
	}

	function bindSystemCheck() {
		bindInstallationSettings()
		bindRetentionPolicy()
		document.getElementById('run-system-check')?.addEventListener('click', async () => {
			try { await loadSystemCheck(); render() }
			catch (error) { ctx.notifyError(error.message) }
		})
		root.querySelectorAll('.bp-system-action').forEach((button) => button.addEventListener('click', async () => {
			const view = button.dataset.systemView
			const tab = button.dataset.systemTab
			if (view === 'administration') {
				state.view = 'administration'; state.administrationTab = tab || 'system'
				if (tab === 'branches') state.branches = await api(`${ctx.apiBase}/branches`)
			} else if (view === 'customizing') {
				state.view = 'customizing'; state.customizingTab = tab || 'documents'
				if (tab === 'documents') [state.documentTemplates, state.documentTemplateOptions] = await Promise.all([api(`${ctx.apiBase}/document-templates`), api(`${ctx.apiBase}/document-template-options`)])
				if (tab === 'workflows') state.workflowAdmin = await api(`${ctx.apiBase}/workflows`)
			} else if (view === 'task') {
				state.view = 'task'; state.records.task = await api(`${ctx.apiBase}/records/task`)
			} else if (view === 'cases') {
				state.view = 'cases'
			}
			render()
		}))
	}

	function branchesView() {
		const profiles = state.countryProfiles || []
		const profileOptions = (selected) => profiles.map((profile) => `<option value="${esc(profile.countryCode)}" ${profile.countryCode === selected ? 'selected' : ''} ${profile.ready ? '' : 'disabled'}>${esc(profile.countryCode)} – ${esc(profile.name)}${profile.ready ? '' : ' (vorbereitet)'}</option>`).join('')
		const atStates = profiles.find((profile) => profile.countryCode === 'AT')?.federalStates || []
		const stateOptions = (selected) => `<option value="">Bundesland wählen</option>${atStates.map((item) => `<option value="${esc(item.key)}" ${item.key === selected ? 'selected' : ''}>${esc(item.label)}</option>`).join('')}`
		const profileCards = profiles.filter((profile) => profile.ready).map((profile) => `<article class="bp-country-profile" data-country-profile="${esc(profile.countryCode)}"><header><div><b>${esc(profile.countryCode)} – ${esc(profile.name)}</b><small>Gemeinsamer Katalog; diese Sätze erweitern die installationsweit zulässige Auswahl.</small></div><span>${profile.templateNamespace === 'AT' ? 'Regionalvorlagen erforderlich' : 'Basisprofil'}</span></header><div class="bp-form-grid"><label><span>Zulässige Mehrwertsteuersätze</span><input name="vatRates" value="${esc((profile.vatRates || []).join(', '))}"><small>Kommagetrennt, z. B. 0, 10, 13, 20.</small></label><label><span>Standard-Rechnungsprofil</span><select name="invoiceProfile">${[['ZUGFERD','ZUGFeRD'],['XRECHNUNG','XRechnung'],['NONE','Keine E-Rechnung']].map(([value,label]) => `<option value="${value}" ${profile.invoiceProfile === value ? 'selected' : ''}>${label}</option>`).join('')}</select></label><label><span>Standard-Zahlungs-QR</span><select name="paymentQrStandard"><option value="EPC069-12" ${profile.paymentQrStandard === 'EPC069-12' ? 'selected' : ''}>EPC-SEPA-Zahlcode</option><option value="NONE" ${profile.paymentQrStandard === 'NONE' ? 'selected' : ''}>Kein Zahlungs-QR</option></select></label></div><button type="button" class="bp-secondary save-country-profile">Länderprofil speichern</button><p class="bp-card-state" aria-live="polite"></p></article>`).join('')
		const bankFields = (entry) => `<h4>Bank- und Unternehmensdaten</h4><div class="bp-form-grid"><label><span>Kontoinhaber</span><input name="accountHolder" value="${esc(entry.accountHolder)}"></label><label><span>Bank</span><input name="bankName" value="${esc(entry.bankName)}"></label><label><span>IBAN</span><input name="iban" value="${esc(entry.iban)}" autocomplete="off"></label><label><span>BIC</span><input name="bic" value="${esc(entry.bic)}" autocomplete="off"></label><label><span>Zahlungsziel (Tage)</span><input name="paymentTermDays" type="number" min="0" max="365" value="${Number(entry.paymentTermDays ?? 14)}"></label><label><span>Gläubiger-ID</span><input name="creditorId" value="${esc(entry.creditorId)}"></label><label><span>USt-IdNr.</span><input name="vatId" value="${esc(entry.vatId)}"></label><label><span>Steuernummer</span><input name="taxNumber" value="${esc(entry.taxNumber)}"></label><label><span>Registergericht</span><input name="registerCourt" value="${esc(entry.registerCourt)}"></label><label><span>Registernummer</span><input name="registerNumber" value="${esc(entry.registerNumber)}"></label><label><span>Geschäftsführung</span><input name="managingDirectors" value="${esc(entry.managingDirectors)}"></label><label><span>E-Rechnungs-Adresse</span><input name="electronicAddress" value="${esc(entry.electronicAddress)}"></label></div><div class="bp-row-actions bp-bank-save"><button type="button" class="bp-primary save-branch-bank" data-id="${entry.id}">Bank- und Unternehmensdaten speichern</button></div>`
		const cards = state.branches.map((entry) => `<article class="bp-checklist-editor" data-branch-id="${entry.id}"><div class="bp-form-grid"><label><span>Niederlassungsschlüssel</span><input name="key" value="${esc(entry.key)}" pattern="[A-Za-z0-9_-]+" required><small>Nur Buchstaben, Ziffern, _ und -; keine Leerzeichen.</small></label><label><span>Name</span><input name="name" value="${esc(entry.name)}" required></label><label><span>Länderprofil</span><select name="countryCode">${profileOptions(entry.countryCode || 'DE')}</select><small>Steuert Steuer-, Rechnungs-, Zahlungs- und Vorlagenlogik.</small></label><label class="bp-federal-state ${entry.countryCode === 'AT' ? '' : 'bp-hidden'}"><span>Bundesland</span><select name="federalState">${stateOptions(entry.federalState || '')}</select></label><label><span>Land im Anschriftentext</span><input name="country" value="${esc(entry.country || 'Deutschland')}"></label><label><span>Rechnungsprofil</span><select name="invoiceProfile">${[['ZUGFERD','ZUGFeRD'],['XRECHNUNG','XRechnung'],['NONE','Keine E-Rechnung']].map(([value,label]) => `<option value="${value}" ${entry.invoiceProfile === value ? 'selected' : ''}>${label}</option>`).join('')}</select></label><label><span>Zahlungs-QR</span><select name="paymentQrStandard"><option value="EPC069-12" ${entry.paymentQrStandard !== 'NONE' ? 'selected' : ''}>EPC-SEPA-Zahlcode</option><option value="NONE" ${entry.paymentQrStandard === 'NONE' ? 'selected' : ''}>Kein Zahlungs-QR</option></select></label><label><span>Straße und Hausnummer</span><input name="street" value="${esc(entry.street)}"></label><label><span>Postleitzahl</span><input name="postalCode" value="${esc(entry.postalCode)}"></label><label><span>Ort</span><input name="city" value="${esc(entry.city)}"></label><label><span>Telefon</span><input name="phone" value="${esc(entry.phone)}"></label><label><span>E-Mail</span><input name="email" type="email" value="${esc(entry.email)}"></label></div>${bankFields(entry)}<fieldset class="bp-member-picker"><legend>Mitarbeiter aus der Gruppe Bestatter</legend>${state.team.members.map((member) => `<label class="bp-inline-check"><input type="checkbox" name="memberUids" value="${esc(member.uid)}" ${(entry.memberUids || []).includes(member.uid) ? 'checked' : ''}> <span>${esc(member.displayName || member.uid)} <small>${esc(member.uid)}</small></span></label>`).join('') || '<p class="bp-muted">Keine Mitglieder der Gruppe Bestatter gefunden.</p>'}</fieldset><label class="bp-inline-check"><input name="active" type="checkbox" ${entry.active ? 'checked' : ''}> Aktiv</label><p class="bp-card-state" aria-live="polite"></p><div class="bp-row-actions"><button class="bp-secondary save-branch" data-id="${entry.id}">Speichern</button><button class="bp-danger delete-branch" data-id="${entry.id}">Löschen</button></div></article>`).join('')
		return `<section class="bp-panel bp-config-admin"><div class="bp-panel-head"><div><h3>Länderprofile</h3><p class="bp-muted">Zentrale Regeln für den gemeinsamen Leistungskatalog. Schweiz und Frankreich bleiben sichtbar vorbereitet, sind aber noch nicht freigegeben.</p></div></div><div class="bp-country-profile-grid">${profileCards}</div></section><section class="bp-panel bp-config-admin"><div class="bp-panel-head"><div><h3>Niederlassungen</h3><p class="bp-muted">Adresse, Mitarbeiterzuordnung und verbindliches Länderprofil je Niederlassung.</p></div><button class="bp-primary" id="new-branch">+ Niederlassung</button></div><div class="bp-admin-list">${cards || '<p class="bp-empty">Noch keine Niederlassung angelegt.</p>'}</div></section>`
	}

	function invoiceSettingsView() {
		const s = state.invoiceSettings
		return `<section class="bp-panel bp-config-admin"><div class="bp-panel-head"><div><h3>Rechnungswesen</h3><p class="bp-muted">Nummernkreis, E-Rechnung und Zahlungs-QR zentral konfigurieren.</p></div></div><div class="bp-form-grid" id="invoice-settings"><label><span>Rechnungspräfix</span><input name="prefix" value="${esc(s.prefix)}"><small>Zum Beispiel RE für Rechnung.</small></label><label><span>Aufbau der Rechnungsnummer</span><input name="pattern" value="${esc(s.pattern)}"><small>Die verfügbaren Bausteine werden unterhalb erläutert.</small></label><label><span>Länge der laufenden Nummer</span><input name="sequenceLength" type="number" min="3" max="12" value="${Number(s.sequenceLength)}"><small>Beispiel: 6 Stellen ergeben 000001.</small></label><label><span>Zählweise</span><select name="sequenceScope"><option value="YEAR_GLOBAL" ${s.sequenceScope === 'YEAR_GLOBAL' ? 'selected' : ''}>Jährlich, über alle Niederlassungen</option><option value="YEAR_BRANCH" ${s.sequenceScope === 'YEAR_BRANCH' ? 'selected' : ''}>Jährlich je Niederlassung</option><option value="GLOBAL" ${s.sequenceScope === 'GLOBAL' ? 'selected' : ''}>Fortlaufend ohne Jahreswechsel</option></select></label></div><div class="bp-token-help"><h4>Bausteine für die Rechnungsnummer</h4><p class="bp-muted">Technische Schreibweise: jeweils genau ein Paar geschweifter Klammern.</p><dl><div><dt><code>{PREFIX}</code></dt><dd>Das oben eingestellte Rechnungspräfix, z. B. <b>RE</b>.</dd></div><div><dt><code>{YYYY}</code></dt><dd>Das Rechnungsjahr mit vier Stellen, z. B. <b>2026</b>.</dd></div><div><dt><code>{YY}</code></dt><dd>Das Rechnungsjahr mit zwei Stellen, z. B. <b>26</b>.</dd></div><div><dt><code>{SEQ}</code></dt><dd>Die fortlaufende Rechnungsnummer in der eingestellten Länge, z. B. <b>000001</b>.</dd></div><div><dt><code>{CASE}</code></dt><dd>Die Nummer des zugehörigen Sterbefalls, z. B. <b>2026-0006</b>.</dd></div><div><dt><code>{BRANCH}</code></dt><dd>Der Niederlassungsschlüssel des Falls, z. B. <b>STAMMHAUS</b>.</dd></div></dl><p class="bp-muted">Empfohlener Aufbau: <code>{PREFIX}-{YYYY}-{SEQ}</code> → <b>RE-2026-000001</b>. Die Fallnummer wird zusätzlich als eigene Referenz auf der Rechnung ausgegeben.</p></div><p><b>Aktuelle Vorschau:</b> <code>${esc(s.preview)}</code></p><div class="bp-inline-options"><label class="bp-inline-check"><input name="caseReference" type="checkbox" ${s.caseReference ? 'checked' : ''}> Fallnummer als separate Referenz ausgeben</label><label class="bp-inline-check"><input name="zugferdEnabled" type="checkbox" ${s.zugferdEnabled ? 'checked' : ''}> ZUGFeRD 2.5.2 / EN16931</label><label class="bp-inline-check"><input name="xrechnungEnabled" type="checkbox" ${s.xrechnungEnabled ? 'checked' : ''}> XRechnung 3.0.x als CII-XML ausgeben</label><label class="bp-inline-check"><input name="normativeValidationRequired" type="checkbox" ${s.normativeValidationRequired ? 'checked' : ''}> Normative Prüfung vor Ausgabe zwingend verlangen</label><label class="bp-inline-check"><input name="qrEnabled" type="checkbox" ${s.qrEnabled ? 'checked' : ''}> EPC-SEPA-Zahlcode</label></div><aside class="bp-compliance-note"><h4>Zwei unterschiedliche Prüfstufen</h4><p><b>Strukturell geprüft:</b> Die App kontrolliert XML-Aufbau, Pflichtangaben, Zahlenformate und Rechensummen. Das findet typische Erfassungs- und Dateifehler, ist aber noch keine verbindliche Konformitätsaussage.</p><p><b>Normativ validiert:</b> Ein eingerichteter Mustang-/KoSIT-Validator prüft zusätzlich gegen die offiziellen, versionsabhängigen EN16931-/XRechnung-Regeln. Nur nach diesem externen Prüflauf darf die App diesen Status vergeben.</p></aside><p class="bp-card-state" aria-live="polite"></p><button class="bp-primary" id="save-invoice-settings">Rechnungseinstellungen speichern</button></section>`
	}

	async function loadCommercial() {
		if (!state.currentCase?.id) return
		const sideOrderQuery = Number(state.activeSideOrderId || 0) > 0 ? `?sideOrderId=${Number(state.activeSideOrderId)}` : ''
		state.commercial = await api(`${commercialUrl(state.currentCase.id)}${sideOrderQuery}`)
		state.caseServices = state.commercial.services || state.caseServices
		hydrateServiceDraft()
	}

	function commercialVersionPanel(mode = 'A') {
		const docs = state.commercial.documents || []
		const quotes = docs.filter((item) => item.documentType === 'QUOTE')
		const orders = docs.filter((item) => item.documentType === 'ORDER')
		const hasOrder = orders.length > 0
		const rows = docs.map((item) => { const converted = item.documentType === 'QUOTE' && (hasOrder || item.status === 'UEBERNOMMEN' || item.convertedOrderId); let action = '<span class="bp-muted">Verbindlicher Auftrag</span>'; if (item.documentType === 'QUOTE') action = converted ? '<span class="bp-muted">Übernommen · nur Nachweis</span>' : `<button type="button" class="bp-secondary convert-quote" data-quote-id="${item.id}" title="In Auftrag übernehmen">Einmalig in Auftrag übernehmen</button>`; return `<tr><td>${item.documentType === 'QUOTE' ? 'KVA' : 'Auftrag'}</td><td><b>${esc(item.documentNumber)}</b></td><td>V${item.version}</td><td>${esc(converted ? 'UEBERNOMMEN' : item.status)}</td><td>${new Date(item.createdAt).toLocaleString('de-DE')}</td><td>${action}</td></tr>` }).join('')
		const freezeButton = !hasOrder && !quotes.length
			? (mode === 'KVA' ? '<button type="button" class="bp-primary" id="freeze-quote" title="KVA-Version festschreiben">KVA als PDF festschreiben</button>' : '<button type="button" class="bp-primary" id="freeze-order" title="Auftrag verbindlich festschreiben">Auftrag verbindlich festschreiben</button>')
			: ''
		return `<section class="bp-field-section bp-commercial-versions"><div class="bp-panel-head"><div><h3>KVA- und Auftragsnachweise</h3><p class="bp-muted">KVA und direkte Aufträge werden als unveränderlicher Nachweis festgeschrieben. Ein KVA kann anschließend genau einmal in einen Auftrag übernommen werden.</p></div>${freezeButton}</div>${orders.length > 1 ? '<div class="bp-warning"><b>Historische Mehrfachaufträge vorhanden.</b> Sie bleiben aus Gründen der Nachvollziehbarkeit sichtbar; eine weitere Übernahme ist technisch gesperrt.</div>' : ''}<div class="bp-table-scroll"><table><thead><tr><th>Art</th><th>Nummer</th><th>Version</th><th>Status</th><th>Erstellt</th><th>Aktion</th></tr></thead><tbody>${rows || '<tr><td colspan="6" class="bp-empty">Noch kein festgeschriebener Nachweis.</td></tr>'}</tbody></table></div>${quotes.length || hasOrder ? '' : `<p class="bp-muted">${mode === 'KVA' ? 'Für eine KVA-Übernahme muss zunächst der KVA festgeschrieben werden.' : 'Der direkte Auftrag muss vor der Rechnungsstellung verbindlich festgeschrieben werden.'}</p>`}</section>`
	}

	const incomingClassificationLabels = {
		TRUE_PASS_THROUGH: 'Durchlaufender Posten im fremden Namen',
		THIRD_PARTY_SERVICE: 'Fremdleistung des Bestatters',
		EXPENSE_FEE: 'Auslage / Gebühr',
		NOT_BILLABLE: 'Nicht an Kunden berechnen',
		CLASSIFICATION_PENDING: 'Noch fachlich zu prüfen',
	}
	const incomingStatusLabels = { ENTWURF: 'Erfasst', PRUEFUNG: 'In Prüfung', ZUGEORDNET: 'Übernommen', FREIGEGEBEN: 'Freigegeben', ABGELEHNT: 'Abgelehnt' }
	const incomingFlowSteps = ['Beleg', 'Rechnungsdaten', 'Positionsabgleich', 'Übernahme', 'Freigabe']
	const incomingFlowPosition = { ENTWURF: 2, PRUEFUNG: 3, ZUGEORDNET: 4, FREIGEGEBEN: 5, ABGELEHNT: 0 }

	function incomingFlow(status) {
		const current = incomingFlowPosition[status] ?? 1
		return `<ol class="bp-incoming-flow" aria-label="Bearbeitungsstand Eingangsrechnung">${incomingFlowSteps.map((label, index) => { const position=index+1; const stateClass=status==='ABGELEHNT'?'rejected':position<current?'complete':position===current?'current':'pending'; return `<li class="${stateClass}" ${position===current?'aria-current="step"':''}><span>${position}</span><b>${label}</b></li>` }).join('')}</ol>`
	}

	function incomingInvoicePanel() {
		const data = state.commercial.incomingInvoices || { items: [] }
		const rows = (data.items || []).map((invoice) => {
			const difference = Number(invoice.differenceCents || 0)
			const file = invoice.fileId ? `<button type="button" class="bp-secondary open-incoming-file" data-file-id="${invoice.fileId}">Beleg öffnen</button>` : '<span class="bp-muted">Kein Beleg</span>'
			const edit = invoice.canEdit ? `<button type="button" class="bp-secondary edit-incoming-invoice" data-id="${invoice.id}">Prüfen / bearbeiten</button>` : ''
			const transfer = invoice.canTransfer ? `<button type="button" class="bp-primary transfer-incoming-invoice" data-id="${invoice.id}">Positionen übernehmen</button>` : ''
			const paperless = invoice.paperless ? `<p class="bp-paperless-state"><b>Paperless:</b> ${esc(invoice.paperless.status)}${invoice.paperless.documentId ? ` · Dokument ${esc(invoice.paperless.documentId)}` : ''}${invoice.paperless.error ? ` · ${esc(invoice.paperless.error)}` : ''}${['FAILED','RETRY'].includes(invoice.paperless.status) ? ` <button type="button" class="bp-secondary retry-paperless" data-external-id="${invoice.paperless.id}">Erneut übertragen</button>` : ''}</p>` : '<p class="bp-muted">Paperless: nicht verknüpft oder deaktiviert – der Nextcloud-Beleg ist vollständig nutzbar.</p>'
			const transitions = invoice.status === 'ENTWURF' ? `<button type="button" class="bp-secondary transition-incoming-invoice" data-id="${invoice.id}" data-status="PRUEFUNG">Zur Prüfung</button><button type="button" class="bp-secondary transition-incoming-invoice" data-id="${invoice.id}" data-status="ABGELEHNT">Ablehnen</button>` : invoice.status === 'PRUEFUNG' ? `<button type="button" class="bp-secondary transition-incoming-invoice" data-id="${invoice.id}" data-status="ENTWURF">Zurück zum Entwurf</button><button type="button" class="bp-secondary transition-incoming-invoice" data-id="${invoice.id}" data-status="ABGELEHNT">Ablehnen</button>` : invoice.status === 'ZUGEORDNET' ? `<button type="button" class="bp-primary transition-incoming-invoice" data-id="${invoice.id}" data-status="FREIGEGEBEN">Freigeben</button>` : ''
			const positions = (invoice.items || []).map((item) => `<li><span>${item.position}. ${esc(item.description)}</span><small>${esc(incomingClassificationLabels[item.classification] || item.classification)} · ${esc(item.transferStatus)}</small></li>`).join('')
			const blockers = [Math.abs(difference)>1?`Summendifferenz ${formatMoney(difference)}`:'',Number(invoice.pendingClassifications||0)>0?`${invoice.pendingClassifications} ungeklärte Klassifikation(en)`:'' ].filter(Boolean)
			const next = invoice.status==='ENTWURF'?'Rechnungsdaten und Positionen prüfen und anschließend „Zur Prüfung“ wählen.':invoice.status==='PRUEFUNG'?(blockers.length?`Vor der Übernahme klären: ${blockers.join(' · ')}`:'Alle Prüfungen sind erfüllt. Positionen können jetzt einmalig übernommen werden.'):invoice.status==='ZUGEORDNET'?'Die Positionen sind Fallleistungen zugeordnet. Abschließend fachlich freigeben.':invoice.status==='FREIGEGEBEN'?'Bearbeitung abgeschlossen; die übernommenen Positionen stehen für die Kundenabrechnung bereit.':'Die Eingangsrechnung wurde abgelehnt und wird nicht übernommen.'
			return `<article class="bp-incoming-card status-${String(invoice.status).toLowerCase()}"><div class="bp-panel-head"><div><p class="bp-eyebrow">${esc(invoice.supplierName)}</p><h4>${esc(invoice.supplierInvoiceNumber)}</h4><p class="bp-muted">Rechnung ${esc(invoice.invoiceDate)} · Eingang ${esc(invoice.receivedDate)}${invoice.dueDate ? ` · fällig ${esc(invoice.dueDate)}` : ''}</p></div><span class="bp-status">${esc(incomingStatusLabels[invoice.status]||invoice.status)}</span></div>${incomingFlow(invoice.status)}<div class="bp-incoming-totals"><span>Belegsumme <b>${formatMoney(invoice.declaredGrossCents)}</b></span><span>Positionssumme <b>${formatMoney(invoice.totals?.grossCents)}</b></span><span class="${Math.abs(difference) <= 1 ? 'ok' : 'error'}">Differenz <b>${formatMoney(difference)}</b></span></div><ul class="bp-incoming-positions">${positions}</ul>${paperless}<p class="bp-incoming-next"><b>Nächster Schritt:</b> ${esc(next)}</p>${invoice.notes ? `<p class="bp-muted">${esc(invoice.notes)}</p>` : ''}<div class="bp-row-actions">${file}${edit}${transitions}${transfer}</div></article>`
		}).join('')
		return `<section class="bp-field-section bp-incoming-invoices"><div class="bp-panel-head"><div><h3>Eingangsrechnungen und durchlaufende Posten</h3><p class="bp-muted">Geführte Verarbeitung von Fremdkosten vom Originalbeleg bis zur abrechenbaren Fallleistung. Eine vorhandene Fallleistung stammt aus KVA/Auftrag; fehlt sie, kann kontrolliert eine einmalige Zusatzleistung angelegt werden.</p></div><button type="button" class="bp-primary" id="new-incoming-invoice">+ Eingangsrechnung erfassen</button></div><div class="bp-process-explainer"><b>Was wird abgeglichen?</b><span>Lieferantenrechnung ↔ beauftragte beziehungsweise erbrachte Fallleistung ↔ vorgesehene Kundenabrechnung.</span><small>Eine eigenständige Lieferantenbestellung oder ein Wareneingang wird in dieser Ausbaustufe noch nicht geführt.</small></div><div class="bp-incoming-list">${rows || '<p class="bp-empty">Noch keine Eingangsrechnung für diesen Fall erfasst.</p>'}</div><p class="bp-muted">Der Ablauf funktioniert vollständig ohne Paperless-ngx. Eine spätere Paperless-Anbindung unterstützt nur Eingang und Datenerkennung; Prüfung, Zuordnung und Freigabe bleiben in der Bestatter-App.</p></section>`
	}

	function showIncomingInvoiceForm(invoice = null) {
		const units = state.commercial.incomingInvoices?.units || ['STK', 'PAUSCHAL', 'STD', 'KM', 'TAG']
		const classifications = state.commercial.incomingInvoices?.classifications || Object.keys(incomingClassificationLabels)
		const services = state.caseServices.items || []
		const serviceOptions = (value = 0) => `<option value="0">Keine passende Position – einmalige Zusatzleistung anlegen</option>${services.map((service) => `<option value="${service.id}" ${Number(value) === Number(service.id) ? 'selected' : ''}>${esc(service.articleNumber)} · ${esc(service.title)}</option>`).join('')}`
		const serviceSummary = (value = 0) => { const service=services.find((entry)=>Number(entry.id)===Number(value)); return service?`Auftrags-/Fallleistung: ${esc(service.title)} · beauftragt ${esc(formatQuantity(service.quantity,service.quantityDecimals))} ${esc(service.unit)} · VK netto ${formatMoney(service.unitPriceCents)}`:'Keine passende Auftragsposition: Bei der Übernahme wird eine einmalige, nur diesem Fall zugeordnete Zusatzleistung angelegt.' }
		const row = (item = {}) => `<div class="bp-incoming-item" data-incoming-item><div class="bp-incoming-item-head"><b>Rechnungsposition</b><button type="button" class="bp-danger remove-incoming-item">Position entfernen</button></div><div class="bp-incoming-supplier-fields bp-form-grid"><label class="bp-span-2"><span>Bezeichnung laut Lieferantenrechnung</span><input name="description" value="${esc(item.description || '')}" required></label><label><span>Berechnete Menge</span><input name="supplierQuantity" type="number" min="0.001" step="0.001" value="${Number(item.supplierQuantity ?? 1)}" required></label><label><span>Einheit</span><select name="unit">${units.map((unit) => `<option ${unit === (item.unit || 'STK') ? 'selected' : ''}>${esc(unit)}</option>`).join('')}</select></label><label><span>Einkaufspreis netto je Einheit</span><input name="supplierUnit" type="number" min="0" step="0.01" value="${(Number(item.supplierUnitCents || 0) / 100).toFixed(2)}" required></label><label><span>Vorsteuer laut Beleg</span><select name="supplierVatRate">${[0,7,19].map((rate) => `<option value="${rate}" ${rate === Number(item.supplierVatRate ?? 19) ? 'selected' : ''}>${rate}%</option>`).join('')}</select></label></div><div class="bp-incoming-match-fields bp-form-grid" hidden><label class="bp-span-2"><span>1. Fachlich einordnen</span><select name="classification">${classifications.map((value) => `<option value="${value}" ${value === (item.classification || 'CLASSIFICATION_PENDING') ? 'selected' : ''}>${esc(incomingClassificationLabels[value] || value)}</option>`).join('')}</select><small>„Durchlaufender Posten“ nur wählen, wenn die steuerliche Einordnung verbindlich geklärt ist.</small></label><label class="bp-span-2"><span>2. Vorhandener Auftrags-/Fallleistung zuordnen</span><select name="caseServiceId">${serviceOptions(item.caseServiceId)}</select><small class="bp-service-match-summary">${serviceSummary(item.caseServiceId)}</small></label><label><span>3. Kundenmenge</span><input name="customerQuantity" type="number" min="0.001" step="0.001" value="${Number(item.customerQuantity ?? item.supplierQuantity ?? 1)}"></label><label><span>Verkaufspreis netto je Einheit</span><input name="customerUnit" type="number" min="0" step="0.01" value="${(Number(item.customerUnitCents ?? item.supplierUnitCents ?? 0) / 100).toFixed(2)}"></label><label><span>Umsatzsteuer Kunde</span><select name="customerVatRate">${[0,7,19].map((rate) => `<option value="${rate}" ${rate === Number(item.customerVatRate ?? item.supplierVatRate ?? 19) ? 'selected' : ''}>${rate}%</option>`).join('')}</select></label><label class="bp-span-2"><span>Begründung bei Preis-, Mengen- oder Steuerabweichung</span><input name="varianceReason" value="${esc(item.varianceReason || '')}" placeholder="z. B. Zusatzlieferung oder vereinbarter Verkaufspreis"></label></div></div>`
		const items = invoice?.items?.length ? invoice.items : [{}]
		root.insertAdjacentHTML('beforeend', `<div class="bp-modal"><form id="incoming-invoice-form" class="bp-wide-modal bp-incoming-wizard" data-step="1"><div class="bp-panel-head"><div><h2>${invoice ? 'Eingangsrechnung prüfen' : 'Eingangsrechnung erfassen'}</h2><p class="bp-muted">Schrittweise vom Originalbeleg zur kontrollierten Fallzuordnung.</p></div><button type="button" class="bp-secondary" id="cancel-incoming-invoice">Schließen</button></div><ol class="bp-wizard-steps" aria-label="Schritte der Eingangsrechnungsverarbeitung">${['Beleg und Kopf','Lieferantenpositionen','Zuordnung','Prüfung','Abschluss'].map((label,index)=>`<li><button type="button" data-incoming-step="${index+1}" ${index?'disabled':''}><span>${index+1}</span>${label}</button></li>`).join('')}</ol><section data-incoming-stage="1"><div class="bp-process-explainer"><b>Originalbeleg unverändert ablegen</b><span>Die Datei wird unter „06 Abrechnung“ gespeichert und gegen bereits erfasste Belege geprüft.</span></div><div class="bp-form-grid"><label><span>Lieferant</span><input name="supplierName" list="incoming-suppliers" value="${esc(invoice?.supplierName || '')}" required><datalist id="incoming-suppliers">${contactsByCategory('Lieferant').map((contact) => `<option value="${esc(contact.title)}"></option>`).join('')}</datalist></label><label><span>Lieferanten-Rechnungsnummer</span><input name="supplierInvoiceNumber" value="${esc(invoice?.supplierInvoiceNumber || '')}" required></label><label><span>Rechnungsdatum</span><input name="invoiceDate" type="date" value="${esc(invoice?.invoiceDate || new Date().toISOString().slice(0,10))}" required></label><label><span>Eingangsdatum</span><input name="receivedDate" type="date" value="${esc(invoice?.receivedDate || new Date().toISOString().slice(0,10))}" required></label><label><span>Fällig am</span><input name="dueDate" type="date" value="${esc(invoice?.dueDate || '')}"></label><label><span>Bruttobetrag laut Beleg</span><input name="declaredGross" type="number" min="0.01" step="0.01" value="${(Number(invoice?.declaredGrossCents || 0)/100).toFixed(2)}" required></label>${invoice ? '<div class="bp-span-2 bp-success"><b>Originalbeleg ist bereits abgelegt.</b> Beim Bearbeiten wird die Originaldatei nicht verändert.</div>' : '<label class="bp-span-2"><span>Originalbeleg</span><input name="file" type="file" accept="application/pdf,image/jpeg,image/png,image/tiff,application/xml,text/xml" required><small>PDF, Bild oder strukturierte XML-Rechnung; maximal 50 MB.</small></label>'}<label class="bp-span-2"><span>Prüfnotiz</span><textarea name="notes" rows="2">${esc(invoice?.notes || '')}</textarea></label></div></section><section class="bp-field-section bp-incoming-items-stage" hidden><div class="bp-panel-head"><div><h3 id="incoming-stage-title">Lieferantenpositionen erfassen</h3><p class="bp-muted" id="incoming-stage-hint"></p></div><button type="button" class="bp-secondary" id="add-incoming-item">+ Position</button></div><div id="incoming-item-list">${items.map(row).join('')}</div></section><section data-incoming-stage="4" hidden><h3>Prüfergebnis</h3><div id="incoming-review" class="bp-incoming-review" aria-live="polite"></div></section><section data-incoming-stage="5" hidden><h3>Entwurf sicher speichern</h3><div class="bp-process-explainer"><b>Noch keine automatische Übernahme</b><span>Nach dem Speichern bleibt die Eingangsrechnung kontrollierbar. Erst „Zur Prüfung“ und anschließend „Positionen übernehmen“ erzeugt beziehungsweise aktualisiert abrechenbare Fallleistungen.</span><small>Damit werden ungeprüfte Lieferantenwerte niemals automatisch an den Kunden weiterberechnet.</small></div></section><div class="bp-wizard-actions"><button type="button" class="bp-secondary" id="incoming-step-back" hidden>Zurück</button><span class="bp-card-state" id="incoming-save-state" aria-live="polite"></span><button type="button" class="bp-primary" id="incoming-step-next">Weiter</button><button class="bp-primary" id="incoming-submit" hidden>${invoice?'Änderungen speichern':'Entwurf speichern'}</button></div></form></div>`)
		const form = document.getElementById('incoming-invoice-form')
		const number=(value)=>Number(String(value||0).replace(',','.'))
		const collectData=()=>{const invoiceItems=[...form.querySelectorAll('[data-incoming-item]')].map((element)=>({description:element.querySelector('[name="description"]').value,supplierQuantityMilli:Math.round(number(element.querySelector('[name="supplierQuantity"]').value)*1000),unit:element.querySelector('[name="unit"]').value,supplierUnitCents:Math.round(number(element.querySelector('[name="supplierUnit"]').value)*100),supplierVatRate:Number(element.querySelector('[name="supplierVatRate"]').value),classification:element.querySelector('[name="classification"]').value,caseServiceId:Number(element.querySelector('[name="caseServiceId"]').value),customerQuantityMilli:Math.round(number(element.querySelector('[name="customerQuantity"]').value)*1000),customerUnitCents:Math.round(number(element.querySelector('[name="customerUnit"]').value)*100),customerVatRate:Number(element.querySelector('[name="customerVatRate"]').value),varianceReason:element.querySelector('[name="varianceReason"]').value}));return{supplierName:form.elements.supplierName.value,supplierInvoiceNumber:form.elements.supplierInvoiceNumber.value,invoiceDate:form.elements.invoiceDate.value,receivedDate:form.elements.receivedDate.value,dueDate:form.elements.dueDate.value,declaredGrossCents:Math.round(number(form.elements.declaredGross.value)*100),notes:form.elements.notes.value,items:invoiceItems}}
		const updateMatchSummaries=()=>form.querySelectorAll('[data-incoming-item]').forEach((element)=>{const select=element.querySelector('[name="caseServiceId"]');element.querySelector('.bp-service-match-summary').innerHTML=serviceSummary(select.value);select.onchange=()=>{element.querySelector('.bp-service-match-summary').innerHTML=serviceSummary(select.value)}})
		const bindRows = () => { form.querySelectorAll('.remove-incoming-item').forEach((button) => { button.onclick = () => { if (form.querySelectorAll('[data-incoming-item]').length > 1) { button.closest('[data-incoming-item]').remove(); updateReview() } } }); updateMatchSummaries() }
		const validateVisible=()=>{const required=[...form.querySelectorAll(':not([hidden]) input[required], :not([hidden]) select[required]')].filter((field)=>field.offsetParent!==null);for(const field of required){if(!field.checkValidity()){field.reportValidity();return false}}return true}
		const updateReview=()=>{const data=collectData();let positionsGross=0;let pending=0;let newServices=0;let variances=0;data.items.forEach((item)=>{const net=Math.round(item.supplierQuantityMilli*item.supplierUnitCents/1000);positionsGross+=net+Math.round(net*item.supplierVatRate/100);if(item.classification==='CLASSIFICATION_PENDING')pending++;if(!item.caseServiceId)newServices++;if(item.varianceReason.trim())variances++});const difference=data.declaredGrossCents-positionsGross;document.getElementById('incoming-review').innerHTML=`<div class="bp-review-grid"><article class="${Math.abs(difference)<=1?'ok':'error'}"><b>Summenabgleich</b><span>Beleg ${formatMoney(data.declaredGrossCents)} · Positionen ${formatMoney(positionsGross)}</span><small>${Math.abs(difference)<=1?'Beträge stimmen überein.':`Differenz ${formatMoney(difference)} – bitte Positionen korrigieren.`}</small></article><article class="${pending?'warning':'ok'}"><b>Fachliche Einordnung</b><span>${pending?`${pending} Position(en) noch ungeklärt`:'Alle Positionen klassifiziert'}</span></article><article><b>Zuordnung</b><span>${data.items.length-newServices} vorhandene Fallleistung(en)</span><small>${newServices} einmalige Zusatzleistung(en)</small></article><article><b>Abweichungen</b><span>${variances} begründete Abweichung(en)</span></article></div><p class="bp-muted">Der Entwurf darf unvollständig gespeichert werden. Summendifferenzen und ungeklärte Klassifikationen sperren später die Übernahme.</p>`}
		let step=1
		const setStep=(next)=>{step=Math.max(1,Math.min(5,next));form.dataset.step=String(step);form.querySelector('[data-incoming-stage="1"]').hidden=step!==1;form.querySelector('.bp-incoming-items-stage').hidden=![2,3].includes(step);form.querySelectorAll('.bp-incoming-supplier-fields').forEach((element)=>element.hidden=step!==2);form.querySelectorAll('.bp-incoming-match-fields').forEach((element)=>element.hidden=step!==3);form.querySelector('[data-incoming-stage="4"]').hidden=step!==4;form.querySelector('[data-incoming-stage="5"]').hidden=step!==5;form.querySelector('#incoming-step-back').hidden=step===1;form.querySelector('#incoming-step-next').hidden=step===5;form.querySelector('#incoming-submit').hidden=step!==5;form.querySelector('#incoming-stage-title').textContent=step===2?'Lieferantenpositionen erfassen':'Positionen fachlich zuordnen';form.querySelector('#incoming-stage-hint').textContent=step===2?'Werte exakt vom Originalbeleg übernehmen.':'Gegen vorhandene Fallleistungen aus KVA/Auftrag abgleichen oder als einmalige Zusatzleistung kennzeichnen.';form.querySelectorAll('[data-incoming-step]').forEach((button,index)=>{button.disabled=index+1>step+1;button.closest('li').className=index+1<step?'complete':index+1===step?'current':'pending';button.setAttribute('aria-current',index+1===step?'step':'false')});if(step===4)updateReview();form.querySelector('.bp-wide-modal')?.scrollTo?.({top:0,behavior:'smooth'})}
		bindRows(); document.getElementById('cancel-incoming-invoice').onclick = () => root.querySelector('.bp-modal').remove(); document.getElementById('add-incoming-item').onclick = () => { document.getElementById('incoming-item-list').insertAdjacentHTML('beforeend', row()); bindRows() };form.querySelector('#incoming-step-back').onclick=()=>setStep(step-1);form.querySelector('#incoming-step-next').onclick=()=>{if(validateVisible())setStep(step+1)};form.querySelectorAll('[data-incoming-step]').forEach((button)=>button.onclick=()=>{const target=Number(button.dataset.incomingStep);if(target<step||validateVisible())setStep(target)})
		form.onsubmit = async (event) => { event.preventDefault(); const status=document.getElementById('incoming-save-state'); status.textContent='Speichert …'; status.dataset.state='saving'; const data=collectData(); const body=invoice?new URLSearchParams({data:JSON.stringify(data)}):new FormData(); if(!invoice){body.append('data',JSON.stringify(data));if(form.elements.file.files[0])body.append('file',form.elements.file.files[0])} try{await api(invoice?`${ctx.apiBase}/incoming-invoices/${invoice.id}`:`${ctx.apiBase}/cases/${state.currentCase.id}/incoming-invoices`,{method:invoice?'PUT':'POST',body,feedback:false,loadingLabel:'Eingangsrechnung wird gespeichert …'});root.querySelector('.bp-modal').remove();await loadCommercial();render();notifySuccess('Eingangsrechnung wurde als kontrollierbarer Entwurf gespeichert. Nächster Schritt: zur Prüfung geben.')}catch(error){status.textContent=error.message;status.dataset.state='error'} }
	}

	function bindIncomingInvoices() {
		document.getElementById('new-incoming-invoice')?.addEventListener('click', () => showIncomingInvoiceForm())
		root.querySelectorAll('.edit-incoming-invoice').forEach((button) => button.addEventListener('click', () => showIncomingInvoiceForm((state.commercial.incomingInvoices?.items || []).find((item) => item.id === Number(button.dataset.id)))))
		root.querySelectorAll('.open-incoming-file').forEach((button) => button.addEventListener('click', () => window.open(OC.generateUrl(`/f/${button.dataset.fileId}`), '_blank', 'noopener')))
		root.querySelectorAll('.retry-paperless').forEach((button) => button.addEventListener('click', async () => { try { await api(`${ctx.apiBase}/integrations/paperless/documents/${button.dataset.externalId}/retry`, { method:'POST' }); await loadCommercial(); render() } catch(error) { notifyError(error.message) } }))
		root.querySelectorAll('.transfer-incoming-invoice').forEach((button) => button.addEventListener('click', async () => { if(!await confirmAction('Die klassifizierten Positionen jetzt einmalig als abrechenbare Fallleistungen übernehmen?',{title:'Positionen übernehmen',confirmLabel:'Übernehmen'}))return;try{await api(`${ctx.apiBase}/incoming-invoices/${button.dataset.id}/transfer`,{method:'POST'});await loadCommercial();render();notifySuccess('Die Positionen wurden nachvollziehbar in die Fallabrechnung übernommen.')}catch(error){notifyError(error.message)} }))
		root.querySelectorAll('.transition-incoming-invoice').forEach((button) => button.addEventListener('click', async () => { let reason='';if(button.dataset.status==='ABGELEHNT')reason=await promptAction('Grund der Ablehnung','',{title:'Eingangsrechnung ablehnen',label:'Begründung',multiline:true})||'';try{await api(`${ctx.apiBase}/incoming-invoices/${button.dataset.id}/transition`,{method:'POST',body:new URLSearchParams({status:button.dataset.status,reason})});await loadCommercial();render()}catch(error){notifyError(error.message)} }))
	}

	function financesPanel() {
		const check = state.commercial.billingCheck || { result: 'OK', exceptions: [] }
		const sideOrder = state.commercial.sideOrder || null
		const services = state.caseServices.items || []
		const serviceRows = services.map((item) => { const rest=Math.max(0,(Number(item.performedQuantityMilli)-Number(item.invoicedQuantityMilli))/1000); return `<tr><td><b>${esc(item.title)}</b><small>${esc(item.articleNumber)}</small></td><td class="number">${formatQuantity(item.quantity, item.quantityDecimals)} ${esc(unitLabels[item.unit] || item.unit)}</td><td><input class="bp-compact-input" type="number" min="0" step="${quantityStep(item.quantityDecimals)}" data-performed="${item.id}" value="${Number(item.performedQuantity || 0)}" aria-label="Erbrachte Menge ${esc(item.title)}"><small>${esc(unitLabels[item.unit] || item.unit)}</small></td><td class="number">${formatQuantity(Number(item.invoicedQuantityMilli)/1000,item.quantityDecimals)}</td><td class="number"><b>${formatQuantity(rest,item.quantityDecimals)}</b></td><td class="number">${formatMoney(item.unitPriceCents)}</td><td class="number">${formatMoney(item.performedGrossCents)}</td><td><select data-service-status="${item.id}">${(state.commercial.statuses?.service || []).map((status) => `<option ${status === item.serviceStatus ? 'selected' : ''}>${status}</option>`).join('')}</select></td><td><select data-billability="${item.id}">${(state.commercial.statuses?.billability || []).map((status) => `<option ${status === item.billability ? 'selected' : ''}>${status}</option>`).join('')}</select></td><td><input class="bp-reason-input" data-service-reason="${item.id}" value="${esc(item.classificationReason)}" placeholder="Begründung bei Abweichung"></td><td><button class="bp-secondary save-lifecycle" data-service-id="${item.id}">Speichern</button></td></tr>` }).join('')
		const exceptions = (check.exceptions || []).map((item) => `<li class="severity-${item.severity.toLowerCase()}"><b>${esc(item.severity)} · ${esc(item.label)}</b><span>${esc(item.message)}</span></li>`).join('')
		const invoices = (state.commercial.invoices || []).map((item) => { const actions={ENTWURF:[['PRUEFUNG','Zur Prüfung']],PRUEFUNG:[['ENTWURF','Zurück zum Entwurf'],['FREIGEGEBEN','Freigeben']],FREIGEGEBEN:[['VERSENDET','Versand dokumentieren']],VERSENDET:[['TEILBEZAHLT','Teilzahlung'],['BEZAHLT','Bezahlt']],TEILBEZAHLT:[['BEZAHLT','Bezahlt']]}[item.status]||[]; const transitions=actions.map(([status,label])=>`<button class="${status==='FREIGEGEBEN'?'bp-primary':'bp-secondary'} transition-invoice" data-invoice-id="${item.id}" data-status="${status}">${label}</button>`).join(''); const cancel=!['BEZAHLT','STORNIERT'].includes(item.status)?`<button class="bp-secondary transition-invoice" data-invoice-id="${item.id}" data-status="STORNIERT">Stornieren</button>`:''; const generate=item.status==='PRUEFUNG'?`<button class="bp-secondary generate-invoice-document" data-invoice-id="${item.id}" title="Erzeugt den unveränderlichen PDF-Rechnungsabschluss als Grundlage für die anschließende Freigabe.">${item.closureManifest?'Verbindliches Prüfdokument erneut erzeugen':'Verbindliches Prüfdokument erzeugen'}</button>`:''; const period=item.servicePeriodFrom||item.servicePeriodTo?`${item.servicePeriodFrom?new Date(`${item.servicePeriodFrom}T00:00:00`).toLocaleDateString('de-DE'):'…'} – ${item.servicePeriodTo?new Date(`${item.servicePeriodTo}T00:00:00`).toLocaleDateString('de-DE'):'…'}`:'nicht angegeben'; return `<tr><td><b>${esc(item.invoiceNumber)}</b><small>${esc(item.invoiceTypeLabel || 'Teilrechnung')} · Folge ${Number(item.invoiceSequence || 1)}</small></td><td>${esc(item.status)}</td><td>${formatMoney(item.totals.grossCents)}${Number(item.priorGrossCents || 0) ? `<small>Frühere Rechnungen: ${formatMoney(item.priorGrossCents)}</small>` : ''}</td><td><span>${esc(period)}</span><small>${(item.items||[]).length} Position(en)</small></td><td>${new Date(item.createdAt).toLocaleDateString('de-DE')}</td><td><div class="bp-row-actions">${generate}${transitions}${cancel}</div>${item.status==='PRUEFUNG'?'<small>Unveränderlicher PDF-Abschluss; die Rechnung bleibt bis „Freigeben“ im Prüfstatus.</small>':''}</td></tr>` }).join('')
		const ordered = state.caseServices.totals || {}; const performed = state.caseServices.performanceTotals || {}; const invoiced = state.caseServices.invoicedTotals || {}; const outstanding = state.caseServices.outstandingTotals || {}
		return `<section class="bp-panel bp-finances"><div class="bp-page-head"><div><p class="bp-eyebrow">${sideOrder ? `Nebenauftrag ${esc(sideOrder.sideOrderNumber)}` : 'Leistung bis Rechnung'}</p><h2>Abrechnung${sideOrder ? ` · ${esc(`${sideOrder.firstName} ${sideOrder.lastName}`.trim())}` : ''}</h2><p class="bp-muted">Erbrachte Mengen klassifizieren, Abrechnung prüfen und Teil- oder Schlussrechnung erzeugen. Es werden keine E-Mails versendet.</p></div>${sideOrder ? '<button type="button" class="bp-secondary" id="back-to-side-orders-finances">Zur Nebenauftragsübersicht</button>' : ''}</div><section class="bp-field-section"><h3>Leistungserfassung</h3><p class="bp-muted">Die Einheit und zulässigen Nachkommastellen stammen aus dem Leistungskatalog. Beim Speichern werden Menge, Status und Klassifikation unmittelbar an derselben Fallleistung gespeichert; erst „ABRECHENBAR“ nimmt die offene Restmenge in die Fakturierung auf. Die Spalten „bereits fakturiert“ und „offene Restmenge“ zeigen jederzeit, was noch in eine Teilrechnung aufgenommen werden kann.</p><div class="bp-table-scroll"><table><thead><tr><th>Leistung</th><th>Beauftragt</th><th>Erbracht</th><th>Bereits fakturiert</th><th>Offene Restmenge</th><th>Einzel netto</th><th>Erbracht brutto</th><th>Status</th><th>Klassifikation</th><th>Begründung</th><th></th></tr></thead><tbody>${serviceRows || '<tr><td colspan="11" class="bp-empty">Keine Leistungen vorhanden.</td></tr>'}</tbody></table></div><div class="bp-totals"><span>Beauftragt brutto <b>${formatMoney(ordered.grossCents)}</b></span><span>Erbracht netto <b>${formatMoney(performed.netCents)}</b></span><span>MwSt. erbracht <b>${formatMoney(performed.vatCents)}</b></span><span class="grand">Erbracht brutto <b>${formatMoney(performed.grossCents)}</b></span><span>Bereits fakturiert <b>${formatMoney(invoiced.grossCents)}</b></span><span>Noch abrechenbar <b>${formatMoney(outstanding.grossCents)}</b></span></div></section>${sideOrder ? '' : incomingInvoicePanel()}<section class="bp-field-section"><div class="bp-panel-head"><div><h3>Abrechnungssicherheitsprüfung</h3><span class="bp-check-result result-${check.result.toLowerCase()}">${esc(check.result)}</span></div><button class="bp-secondary" id="run-billing-check">Prüfung aktualisieren</button></div><ul class="bp-billing-exceptions">${exceptions || '<li class="severity-ok"><b>Keine Abweichung</b><span>Alle abrechnungsrelevanten Regeln sind erfüllt.</span></li>'}</ul><div class="bp-head-actions"><button class="bp-secondary create-invoice" data-invoice-type="PARTIAL">Teilrechnung auswählen</button><button class="bp-primary create-invoice" data-invoice-type="FINAL">Schlussrechnung vorbereiten</button></div><p class="bp-muted">Bei Teilrechnungen wählen Sie Positionen, Teilmengen und Leistungszeitraum. Die Schlussrechnung übernimmt alle offenen Restmengen und sperrt danach weitere Rechnungsentwürfe.</p></section><section class="bp-field-section"><h3>Rechnungen</h3><div class="bp-table-scroll"><table><thead><tr><th>Nummer / Art</th><th>Status</th><th>Brutto</th><th>Leistungszeitraum</th><th>Erstellt</th><th>Aktion</th></tr></thead><tbody>${invoices || '<tr><td colspan="6" class="bp-empty">Noch keine Rechnung.</td></tr>'}</tbody></table></div></section></section>`
	}

	function administration() {
		const tabs = (active) => `<div class="bp-subtabs bp-admin-tabs"><div><button ${active === 'onboarding' ? 'class="active"' : ''} data-administration-tab="onboarding">Ersteinrichtung</button><button ${active === 'cockpit' ? 'class="active"' : ''} data-administration-tab="cockpit">Betriebs-Cockpit</button><button ${active === 'services' ? 'class="active"' : ''} data-administration-tab="services">Leistungen</button><button ${active === 'branches' ? 'class="active"' : ''} data-administration-tab="branches">Niederlassungen</button><button ${active === 'invoices' ? 'class="active"' : ''} data-administration-tab="invoices">Rechnungswesen</button><button ${active === 'paperless' ? 'class="active"' : ''} data-administration-tab="paperless">Paperless</button><button ${active === 'reports' ? 'class="active"' : ''} data-administration-tab="reports">Kennzahlen & Auswertungen</button><button ${active === 'assistant' ? 'class="active"' : ''} data-administration-tab="assistant">Assistenz</button><button ${active === 'backup' ? 'class="active"' : ''} data-administration-tab="backup">Backup & Restore</button><button ${active === 'system' ? 'class="active"' : ''} data-administration-tab="system">Systemprüfung</button></div><span class="bp-version-badge" title="Installierte Bestatter-App-Version">Version ${esc(ctx.appVersion || '–')}</span></div>`
		if (state.administrationTab === 'onboarding') return `<div class="bp-page-head"><div><p class="bp-eyebrow">Administration</p><h2>Ersteinrichtung</h2><p class="bp-muted">Installation kontrolliert betriebsbereit machen oder den aktuellen Einrichtungsstand prüfen.</p></div></div>${tabs('onboarding')}${onboardingView()}`
		if (state.administrationTab === 'cockpit') return `<div class="bp-page-head"><div><p class="bp-eyebrow">Administration</p><h2>Betriebs-Cockpit</h2><p class="bp-muted">Handlungsbedarf aus Workflows, Paperless, Aufbewahrung und Wartung an einer Stelle.</p></div></div>${tabs('cockpit')}${operationsCockpitView()}`
		if (state.administrationTab === 'branches') return `<div class="bp-page-head"><div><p class="bp-eyebrow">Administration</p><h2>Niederlassungen</h2></div></div>${tabs('branches')}${branchesView()}`
		if (state.administrationTab === 'invoices') return `<div class="bp-page-head"><div><p class="bp-eyebrow">Administration</p><h2>Rechnungswesen</h2></div></div>${tabs('invoices')}${invoiceSettingsView()}`
		if (state.administrationTab === 'paperless') return `<div class="bp-page-head"><div><p class="bp-eyebrow">Administration</p><h2>Paperless-Integration</h2><p class="bp-muted">Optionale Dokumentautomatisierung ohne Abhängigkeit der Fachprozesse.</p></div></div>${tabs('paperless')}${ctx.paperlessSettingsView()}`
		if (state.administrationTab === 'reports') return `<div class="bp-page-head"><div><p class="bp-eyebrow">Administration</p><h2>Kennzahlen und Auswertungen</h2><p class="bp-muted">Fälle, Auslastung, Leistungen und Rechnungsstellung nachvollziehbar auswerten.</p></div></div>${tabs('reports')}${reportingView()}`
		if (state.administrationTab === 'assistant') return `<div class="bp-page-head"><div><p class="bp-eyebrow">Administration</p><h2>Schnellerfassung und KI-Assistenz</h2></div></div>${tabs('assistant')}${assistantSettingsView()}`
		if (state.administrationTab === 'backup') return `<div class="bp-page-head"><div><p class="bp-eyebrow">Administration</p><h2>Backup und Restore</h2><p class="bp-muted">App-Snapshots kontrolliert sichern und Wiederherstellungen sicher vorbereiten.</p></div></div>${tabs('backup')}${backupRestoreView()}`
		if (state.administrationTab === 'system') return `<div class="bp-page-head"><div><p class="bp-eyebrow">Administration</p><h2>Abnahme und Stabilität</h2><p class="bp-muted">Technische Betriebsbereitschaft prüfen, ohne Daten zu verändern.</p></div></div>${tabs('system')}${installationSettingsView()}${operationsReadinessView()}${systemCheckView()}`
		const rows = state.articles.map((article) => `<tr><td><b>${esc(article.articleNumber)}</b><small>${article.itemType === 'PACKAGE' ? 'Paketartikel' : 'Einzelartikel'} | ${article.active ? 'Aktiv' : 'Inaktiv'}</small></td><td><b>${esc(article.shortName)}</b><small>${esc(article.longText || '')}</small></td><td>${esc(article.category)}<small>${esc(article.articleGroup)}${article.exclusiveGroup ? ' · Exklusivgruppe' : ''}</small></td><td>${esc(costTypeLabels[article.costType] || article.costType)}</td><td>${esc(unitLabels[article.unit] || article.unit)}<small>${Number(article.quantityDecimals || 0)} Nachkommastellen</small></td><td class="number">${article.vatRate}%</td><td class="number">${formatMoney(article.purchasePriceCents)}</td><td class="number">${formatMoney(article.salesPriceCents)}</td><td>${esc(article.supplierContact || '-')}<small>${article.photoPath ? 'Foto vorhanden' : 'Kein Foto'}</small></td><td><span class="bp-row-actions"><button class="bp-secondary edit-article" data-article-id="${article.id}">Bearbeiten</button><button class="bp-danger delete-article" data-article-id="${article.id}">Löschen</button></span></td></tr>`).join('')
		const groupRules = (state.articleGroupRules || []).map((rule) => `<label class="bp-group-rule"><span><b>${esc(rule.groupName)}</b><small>${rule.exclusiveSelection ? 'Je Auftrag ist nur eine Position dieser Gruppe zulässig – einschließlich Paketbestandteilen.' : 'Mehrere Positionen dieser Gruppe sind zulässig.'}</small></span><input type="checkbox" data-article-group-rule="${esc(rule.groupName)}" ${rule.exclusiveSelection?'checked':''} aria-label="Exklusive Auswahl für ${esc(rule.groupName)}"></label>`).join('')
		return `<div class="bp-page-head"><div><p class="bp-eyebrow">Administration</p><h2>Leistungen</h2><p class="bp-muted">Zentraler Katalog für Eigenleistungen, Auslagen, Gebühren, Fremdleistungen und Pakete.</p></div><div class="bp-head-actions"><button class="bp-secondary" id="export-articles">CSV exportieren</button><button class="bp-secondary" id="import-articles">CSV aktualisieren</button><button class="bp-primary" id="new-article">+ Leistung anlegen</button><input id="article-csv-file" type="file" accept=".csv,text/csv" hidden></div></div>
		${tabs('services')}<section class="bp-panel bp-group-rules"><div class="bp-panel-head"><div><h3>Auswahlregeln der Artikelgruppen</h3><p class="bp-muted">Aktivieren Sie die Regel für Gruppen wie Sarg oder Urne, aus denen je Auftrag genau eine Alternative zulässig ist. Die Prüfung umfasst Einzelartikel und Bestandteile ausgewählter Pakete.</p></div><span class="bp-save-state" id="group-rule-state">Änderungen werden direkt gespeichert.</span></div><div class="bp-group-rule-grid">${groupRules || '<p class="bp-empty">Noch keine Artikelgruppen vorhanden.</p>'}</div></section><section class="bp-panel bp-article-admin"><div class="bp-admin-hint"><b>Paketartikel</b><span>Pakete setzen sich aus gepflegten Einzelartikeln zusammen. Im Auftrag werden die Bestandteile detailliert ausgewiesen. Eine CSV-Musterdatei liegt im Projektordner importvorlagen.</span></div><div class="bp-table-scroll"><table><thead><tr><th>Artikelnummer</th><th>Bezeichnung</th><th>Kategorie / Gruppe</th><th>Kostenart</th><th>Einheit</th><th class="number">MwSt.</th><th class="number">EK</th><th class="number">VK netto</th><th>Lieferant / Foto</th><th>Aktionen</th></tr></thead><tbody>${rows || '<tr><td colspan="10" class="bp-empty">Noch keine Leistungen vorhanden.</td></tr>'}</tbody></table></div></section>`
	}

	function assistantSettingsView() {
		const settings = state.assistantConfiguration || {}; const providers = settings.providers || {}
		return `<section class="bp-panel"><div class="bp-panel-head"><div><h3>Funktionsstufen</h3><p class="bp-muted">Alle Stufen bleiben unabhängig abschaltbar. Externe KI-Anbieter sind aus Datenschutzgründen standardmäßig nicht zugelassen.</p></div><span class="bp-save-state" id="assistant-settings-state">Noch nicht geändert.</span></div><form id="assistant-settings" class="bp-form-grid">
			<label class="bp-inline-check"><input type="checkbox" name="guidedCaptureEnabled" ${settings.guidedCaptureEnabled ? 'checked' : ''}> Geführte Schnellerfassung aktivieren</label>
			<label class="bp-inline-check"><input type="checkbox" name="speechInputEnabled" ${settings.speechInputEnabled ? 'checked' : ''}> Spracheingabe aktivieren</label>
			<label class="bp-inline-check"><input type="checkbox" name="assistantEnabled" ${settings.assistantEnabled ? 'checked' : ''}> Bestatter-Assistent aktivieren</label>
			<label class="bp-inline-check bp-span-2"><input type="checkbox" name="webResearchEnabled" ${settings.webResearchEnabled ? 'checked' : ''}> Kontrollierte Internetrecherche für öffentliche Organisationen aktivieren</label>
			<p class="bp-muted bp-span-2">Bei der Recherche werden ausschließlich Organisation und Ort an OpenStreetMap/Nominatim übertragen. Fall- und Personendaten werden nicht übermittelt. Treffer müssen vor der Kontaktanlage geprüft und bestätigt werden.</p>
			<label class="bp-inline-check"><input type="checkbox" name="externalAiProvidersAllowed" ${settings.externalAiProvidersAllowed ? 'checked' : ''}> Externe KI-Provider ausdrücklich zulassen</label>
			<label class="bp-inline-check bp-span-2"><input type="checkbox" name="speechProviderApproved" ${settings.speechProviderApproved ? 'checked' : ''}> Den aktuell in Nextcloud konfigurierten Speech-to-Text-Provider nach technischer und datenschutzrechtlicher Prüfung für sensible Falldaten freigeben</label>
			<label><span>Sprache</span><input name="language" value="${esc(settings.language || 'de')}" pattern="[a-z]{2,3}(-[a-z]{2})?"></label>
			<label><span>Audio-Aufbewahrung</span><select name="audioRetention"><option value="DELETE_AFTER_TRANSCRIPTION">Nach Transkription sofort löschen</option></select><small>Eine längere Speicherung ist aus Datenschutzgründen im aktuellen Entwicklungsstand nicht zugelassen.</small></label>
			<div class="bp-span-2 bp-provider-status"><b>Speech-to-Text:</b> ${providers.speechToText ? '<span class="bp-success">verfügbar</span>' : '<span class="bp-warning">noch nicht eingerichtet</span>'}<b>Text-/LLM-Provider:</b> ${providers.textToText ? '<span class="bp-success">verfügbar</span>' : '<span class="bp-warning">noch nicht eingerichtet</span>'}</div>
			<div class="bp-span-2 bp-row-actions"><button class="bp-primary">Einstellungen speichern</button></div>
		</form></section>`
	}

	function bindAssistantSettings() {
		const form = document.getElementById('assistant-settings'); if (!form) return
		form.addEventListener('submit', async (event) => {
			event.preventDefault(); const status = document.getElementById('assistant-settings-state'); const values = Object.fromEntries(new FormData(form))
			for (const key of ['guidedCaptureEnabled','speechInputEnabled','assistantEnabled','webResearchEnabled','externalAiProvidersAllowed','speechProviderApproved']) values[key] = form.elements[key].checked
			status.textContent = 'Speichert …'; status.dataset.state = 'saving'
			try { state.assistantConfiguration = await api(`${ctx.apiBase}/assistant/configuration`, { method: 'PUT', feedback: false, body: new URLSearchParams({ configuration: JSON.stringify(values) }) }); status.textContent = 'Gespeichert'; status.dataset.state = 'saved'; render() }
			catch (error) { status.textContent = error.message; status.dataset.state = 'error' }
		})
	}

	function articleOptions(selectedId = 0) {
		return state.articles.filter((article) => article.itemType === 'SINGLE').map((article) => `<option value="${article.id}" ${article.id === selectedId ? 'selected' : ''}>${esc(article.articleNumber)} | ${esc(article.shortName)}</option>`).join('')
	}

	function packageComponentRows(components = []) {
		const rows = components.length ? components : [{ articleId: 0, quantity: 1 }]
		return rows.map((component) => `<div class="bp-component-row"><select class="component-article"><option value="">Einzelartikel wählen</option>${articleOptions(component.articleId)}</select><input class="component-quantity" type="number" min="0.001" step="0.001" value="${esc(component.quantity || 1)}"><button type="button" class="bp-danger remove-component">Entfernen</button></div>`).join('')
	}

	function supplierOptions(value = '') {
		return `<option value=""></option>${contactsByCategory('Lieferant').map((contact) => `<option value="${esc(contact.title)}" ${contact.title === value ? 'selected' : ''}>${esc(contact.title)}</option>`).join('')}`
	}

	function showArticleForm(item = null) {
		const values = item || { itemType: 'SINGLE', category: 'Dienstleistung', articleGroup: 'Beerdigung/Trauerfeier', costType: 'INTERNAL', funeralScope: 'ALL', unit: 'STK', quantityDecimals: 0, vatRate: 19, active: true, purchasePriceCents: 0, salesPriceCents: 0, components: [] }
		const option = (value, selected) => `<option value="${esc(value)}" ${value === selected ? 'selected' : ''}>${esc(value)}</option>`
		root.insertAdjacentHTML('beforeend', `<div class="bp-modal"><form id="article-form" class="bp-wide-modal"><div class="bp-panel-head"><div><h2>${item ? 'Leistung bearbeiten' : 'Leistung anlegen'}</h2><p class="bp-muted">Preise werden netto gepflegt; die Bruttosumme berechnet der Auftrag.</p></div><button type="button" class="bp-secondary" id="cancel-article">Schließen</button></div><div class="bp-form-grid">
			<label><span>Artikeltyp</span><select name="itemType">${option('SINGLE', values.itemType)}${option('PACKAGE', values.itemType)}</select></label>
			<label><span>Artikelnummer</span><input name="articleNumber" value="${esc(values.articleNumber || '')}" required></label>
			<label class="bp-span-2"><span>Kurzbezeichnung</span><input name="shortName" value="${esc(values.shortName || '')}" required></label>
			<label class="bp-span-2"><span>Langtext</span><textarea name="longText" rows="3">${esc(values.longText || '')}</textarea></label>
			<label><span>Kategorie</span><select name="category">${listOptions('ARTICLE_CATEGORY', values.category)}</select></label>
			<label><span>Gruppe</span><select name="articleGroup">${listOptions('ARTICLE_GROUP', values.articleGroup)}</select></label>
			<label><span>Kostenart</span><select name="costType">${[['INTERNAL', 'Eigene Leistung'], ['EXPENSE', 'Auslage / Gebühr'], ['THIRD_PARTY', 'Fremdleistung']].map(([value, label]) => `<option value="${value}" ${value === values.costType ? 'selected' : ''}>${label}</option>`).join('')}</select></label>
			<label><span>Gültig für</span><select name="funeralScope">${[['ALL', 'Alle Bestattungsarten'], ['BURIAL', 'Erdbestattung'], ['CREMATION', 'Feuer-/Urnenbestattung']].map(([value, label]) => `<option value="${value}" ${value === values.funeralScope ? 'selected' : ''}>${label}</option>`).join('')}</select></label>
			<label><span>Mengeneinheit</span><select name="unit">${Object.entries(unitLabels).map(([value, label]) => `<option value="${value}" ${value === (values.unit || 'STK') ? 'selected' : ''}>${esc(label)}</option>`).join('')}</select></label>
			<label><span>Nachkommastellen der Menge</span><select name="quantityDecimals">${[0, 1, 2, 3].map((value) => `<option value="${value}" ${value === Number(values.quantityDecimals || 0) ? 'selected' : ''}>${value}${value === 0 ? ' (nur ganze Mengen)' : ''}</option>`).join('')}</select><small>Für Stück und Pauschalen wird 0 empfohlen; z. B. Stunden können 2 Nachkommastellen verwenden.</small></label>
			<label><span>Mehrwertsteuer</span><select name="vatRate">${(state.allowedVatRates || [0, 7, 19]).map((value) => `<option value="${value}" ${Number(value) === Number(values.vatRate) ? 'selected' : ''}>${String(value).replace('.', ',')}%</option>`).join('')}</select><small>Aus den freigegebenen Länderprofilen.</small></label>
			<label><span>Standardlieferant</span><select name="supplierContact">${supplierOptions(values.supplierContact)}</select></label>
			<label><span>EK-Preis netto</span><input name="purchasePrice" type="number" min="0" step="0.01" value="${(values.purchasePriceCents / 100).toFixed(2)}"></label>
			<label><span>VK-Preis netto</span><input name="salesPrice" type="number" min="0" step="0.01" value="${(values.salesPriceCents / 100).toFixed(2)}"></label>
			<label><span>Foto (JPG, PNG, WebP)</span><input name="photo" type="file" accept="image/jpeg,image/png,image/webp"><small>${esc(values.photoPath || 'Noch kein Foto hinterlegt')}</small></label>
			<label class="bp-inline-check"><input name="active" type="checkbox" ${values.active ? 'checked' : ''}> Aktiv und im Auftrag auswählbar</label>
			<label class="bp-inline-check"><input name="exclusiveGroup" type="checkbox" ${values.exclusiveGroup ? 'checked' : ''}> In dieser Artikelgruppe darf je Auftrag nur ein Artikel enthalten sein (z. B. Sarg oder Urne)</label><p class="bp-muted bp-span-2">Die Regel gilt für die gesamte Artikelgruppe und wird auch auf Bestandteile von Paketleistungen angewendet.</p>
		</div><section id="package-components" class="bp-package-components ${values.itemType === 'PACKAGE' ? '' : 'bp-hidden'}"><div class="bp-panel-head"><div><h3>Paketbestandteile</h3><p class="bp-muted">Nur Einzelartikel können Bestandteil eines Pakets sein.</p></div><button type="button" class="bp-secondary" id="add-component">+ Bestandteil</button></div><div id="component-rows">${packageComponentRows(values.components || [])}</div></section><div class="bp-modal-actions"><span class="bp-muted">Änderungsdatum: ${esc(values.updatedAt || 'wird beim Speichern gesetzt')}</span><button class="bp-primary">Leistung speichern</button></div></form></div>`)
		const form = document.getElementById('article-form')
		const bindRemove = () => form.querySelectorAll('.remove-component').forEach((button) => { button.onclick = () => { button.closest('.bp-component-row').remove() } })
		bindRemove()
		document.getElementById('cancel-article').onclick = () => root.querySelector('.bp-modal').remove()
		form.elements.itemType.onchange = () => document.getElementById('package-components').classList.toggle('bp-hidden', form.elements.itemType.value !== 'PACKAGE')
		form.elements.articleGroup.onchange = () => { const rule=(state.articleGroupRules||[]).find((entry)=>entry.groupName===form.elements.articleGroup.value); form.elements.exclusiveGroup.checked=Boolean(rule?.exclusiveSelection) }
		document.getElementById('add-component').onclick = () => { document.getElementById('component-rows').insertAdjacentHTML('beforeend', packageComponentRows([])); bindRemove() }
		form.onsubmit = async (event) => {
			event.preventDefault()
			const formData = new FormData(form)
			const article = Object.fromEntries(formData)
			delete article.photo
			article.active = form.elements.active.checked
			article.exclusiveGroup = form.elements.exclusiveGroup.checked
			article.vatRate = Number(article.vatRate)
			article.quantityDecimals = Number(article.quantityDecimals)
			const components = [...form.querySelectorAll('.bp-component-row')].map((row) => ({ articleId: Number(row.querySelector('.component-article').value), quantity: Number(row.querySelector('.component-quantity').value || 1) })).filter((entry) => entry.articleId)
			const saved = await api(item ? `${articleUrl()}/${item.id}` : articleUrl(), { method: item ? 'PUT' : 'POST', body: new URLSearchParams({ article: JSON.stringify(article), components: JSON.stringify(components) }) })
			if (formData.get('photo')?.size) { const upload = new FormData(); upload.append('file', formData.get('photo')); await api(`${articleUrl()}/${saved.id}/photo`, { method: 'POST', body: upload }) }
			const catalog = await api(articleUrl()); state.articles = catalog.articles || []; state.articleGroupRules = catalog.groupRules || []; state.allowedVatRates = catalog.allowedVatRates || state.allowedVatRates; state.countryProfiles = catalog.countryProfiles || state.countryProfiles
			root.querySelector('.bp-modal').remove()
			render()
		}
	}

	function bindArticleAdministration() {
		root.querySelectorAll('[data-article-group-rule]').forEach((input) => input.addEventListener('change', async () => {
			const status = document.getElementById('group-rule-state')
			try {
				if (status) { status.textContent='Speichert …'; status.dataset.state='saving' }
				const catalog = await api(articleGroupUrl(), { method: 'PUT', body: new URLSearchParams({ groupName: input.dataset.articleGroupRule, exclusiveSelection: input.checked ? '1' : '0' }) })
				state.articles = catalog.articles || []; state.articleGroupRules = catalog.groupRules || []; state.allowedVatRates = catalog.allowedVatRates || state.allowedVatRates; state.countryProfiles = catalog.countryProfiles || state.countryProfiles
				if (status) { status.textContent='Gruppenregel gespeichert.'; status.dataset.state='saved' }
				render()
			} catch (error) {
				input.checked = !input.checked
				if (status) { status.textContent=error.message; status.dataset.state='error' }
			}
		}))
		document.getElementById('export-articles')?.addEventListener('click',()=>{const columns=['articleNumber','shortName','longText','category','articleGroup','costType','funeralScope','unit','quantityDecimals','vatRate','purchasePriceCents','salesPriceCents','exclusiveGroup','active','delete'];const quote=(value)=>`"${String(value??'').replaceAll('"','""')}"`;const csv=[columns.join(';'),...state.articles.map((article)=>columns.map((key)=>quote(key==='delete'?'':article[key])).join(';'))].join('\r\n');const blob=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='bestatter-leistungskatalog.csv';link.click();URL.revokeObjectURL(link.href)})
		document.getElementById('new-article')?.addEventListener('click', () => showArticleForm())
		root.querySelectorAll('.edit-article').forEach((button) => button.addEventListener('click', () => showArticleForm(state.articles.find((article) => article.id === Number(button.dataset.articleId)))))
		root.querySelectorAll('.delete-article').forEach((button) => button.addEventListener('click', async () => {
			if (!await confirmAction('Leistung wirklich entfernen? Bei Verwendung in einem Auftrag oder Paket wird sie zum Schutz der Historie deaktiviert.', { title: 'Leistung entfernen', confirmLabel: 'Entfernen', danger: true })) return
			await api(`${articleUrl()}/${button.dataset.articleId}`, { method: 'DELETE' })
			const catalog = await api(articleUrl()); state.articles = catalog.articles || []; state.articleGroupRules = catalog.groupRules || []; state.allowedVatRates = catalog.allowedVatRates || state.allowedVatRates; state.countryProfiles = catalog.countryProfiles || state.countryProfiles
			render()
		}))
		document.getElementById('import-articles')?.addEventListener('click', () => document.getElementById('article-csv-file').click())
		document.getElementById('article-csv-file')?.addEventListener('change', async (event) => {
			if (!event.target.files.length) return
			const body = new FormData(); body.append('file', event.target.files[0])
			const result = await api(`${articleUrl()}/import`, { method: 'POST', body, feedback: false, loadingLabel: 'Leistungskatalog wird importiert …' })
			state.articles = result.articles || []
			state.articleGroupRules = result.groupRules || []
			state.allowedVatRates = result.allowedVatRates || state.allowedVatRates
			state.countryProfiles = result.countryProfiles || state.countryProfiles
			notifySuccess(`${result.imported} Leistungen wurden importiert oder aktualisiert; ${result.deleted||0} wurden gelöscht oder deaktiviert.`)
			render()
		})
	}


	return { branchesView, invoiceSettingsView, assistantSettingsView, reportingView, loadReportingSummary, operationsCockpitView, loadOperationsCockpit, bindOperationsCockpit, bindReporting, loadCommercial, commercialVersionPanel, financesPanel, administration, articleOptions, packageComponentRows, supplierOptions, showArticleForm, bindArticleAdministration, bindIncomingInvoices, bindAssistantSettings, loadSystemCheck, bindSystemCheck, loadBackups, bindBackupRestore, loadOnboarding, bindOnboarding }
}
